const t=[{id:"l.rc-flat.strips-y",xp:30,title:{en:"Tint the strips in the y-direction: the field strip (3.6 m) is wider than the column strip (2.8 m)",ar:"لوّن الشرائح في اتجاه y: الشريحة الوسطى (3.6 م) أعرض من شريحة العمود (2.8 م)"},check:e=>e.strips&&e.dir==="y"},{id:"l.rc-flat.xray",xp:20,title:{en:"X-ray the slab: the top bars crowd over the column lines",ar:"شغّل الأشعة: الحديد العلوي متزاحم فوق خطوط الأعمدة"},check:e=>e.xray}],a=[{id:"l.rc-flat.edge",xp:20,title:{en:"Select an edge column and compare its β and b_o with an interior one",ar:"اختار عمود طرفي وقارن β و b_o بتوعه بعمود داخلي"},check:e=>e.selPos==="edge"},{id:"l.rc-flat.save",xp:50,title:{en:"Make every column pass punching with L.L. still ≥ 3 kN/m² — bigger columns, a thicker slab, drop panels or heads",ar:"خلّي كل الأعمدة تعدّي القص الثاقب والحمل الحي لسه ≥ 3 kN/m² — أعمدة أكبر أو بلاطة أتخن أو سقوط أو تيجان"},check:e=>e.allOk&&e.LL>=3-1e-9}],s=[{id:"l.rc-flat.mf1",xp:30,title:{en:"Make the panels square: the modification factor becomes 1 in both directions",ar:"خلّي البواكي مربعة: معامل التعديل بيبقى 1 في الاتجاهين"},check:e=>e.allMF1},{id:"l.rc-flat.ratio",xp:30,title:{en:"Stretch the panels until L1/L2 > 1.30 and watch the empirical method turn red",ar:"مطّ البواكي لحد ما L1/L2 > 1.30 وشوف الطريقة التقريبية بتحمرّ"},check:e=>!e.eligRatio}],n=[{id:"l.rc-flat.bld-b2",xp:30,title:{en:"Find the column of your floor with the least punching margin",ar:"دوّر على العمود اللي عنده أقل هامش أمان للقص الثاقب في دورك"},check:e=>e.preset==="building"&&e.selId==="B2"},{id:"l.rc-flat.bld-office",xp:50,title:{en:"Turn your floor into offices (L.L. ≥ 3 kN/m²) and keep every column safe with drop panels",ar:"حوّل دورك لمكاتب (الحمل الحي ≥ 3 kN/m²) وخلّي كل الأعمدة آمنة بالسقوط"},check:e=>e.preset==="building"&&e.LL>=3-1e-9&&e.drop&&e.allOk}],i={sections:[{id:"what",title:{en:"Flat slabs: slabs that sit straight on their columns",ar:"البلاطات اللاكمرية: بلاطات قاعدة على أعمدتها مباشرة"},blocks:[{t:"p",text:{en:"A **flat slab** is a reinforced-concrete slab that rests directly on its columns — there are no beams. The ceiling below is flat, so ducts and pipes run anywhere, the formwork is one simple table, and every storey is lower: a 600 mm beam is replaced by a slab about 200 mm thick, so each floor gains about 0.4 m of clear height (or a ten-storey building saves about 4 m of height). The price is a thicker slab, more steel and one dangerous weak point: the slab can **punch** around a column.",ar:"**البلاطة اللاكمرية** بلاطة خرسانة مسلحة قاعدة على أعمدتها مباشرة — مفيش كمرات. السقف اللي تحتها مستوي، فالمواسير والتكييف بيعدّوا في أي حتة، والشدة ترابيزة واحدة بسيطة، وكل دور بيبقى أوطى: كمرة 600 مم بتتشال ويحل محلها بلاطة تخانتها حوالي 200 مم، فكل دور بيكسب حوالي 0.4 م ارتفاع صافي (أو مبنى عشر أدوار بيوفّر حوالي 4 م). التمن: بلاطة أتخن وحديد أكتر ونقطة ضعف خطيرة واحدة: البلاطة ممكن **تتخرم** حوالين العمود (القص الثاقب)."}},{t:"steps",items:[{en:"**Plain flat slab (flat plate)** — one thickness everywhere; light and medium loads, spans up to about 6–7 m.",ar:"**بلاطة لاكمرية عادية (Flat plate)** — تخانة واحدة في كل حتة؛ للأحمال الخفيفة والمتوسطة وبحور لحد حوالي 6–7 م."},{en:'**With drop panels** (السقوط) — the slab is thickened around every column, normally below it; in a top floor it may be cast on top as an "additional panel" to keep the ceiling flat. Used for heavy live loads (5–8 kN/m²), large hogging moments or punching problems.',ar:"**بسقوط (Drop panels)** — البلاطة بتتخن حوالين كل عمود، عادةً من تحت؛ وفي الدور الأخير ممكن تتصب من فوق كـ«بلاطة إضافية» عشان السقف يفضل مستوي. بتستخدم مع الأحمال الحية التقيلة (5–8 kN/m²) أو العزوم السالبة الكبيرة أو مشاكل القص الثاقب."},{en:"**With column heads** (تاج العمود) — the column flares out under the slab (at most 45°), so the slab is pushed over a larger area.",ar:"**بتيجان للأعمدة (Column heads)** — العمود بيوسع تحت البلاطة (بميل 45° بالكتير)، فالبلاطة بتتزق على مساحة أكبر."},{en:"**With marginal beams** (كمرة طرفية) — beams only along the edges: they carry the façade walls and stiffen the free edges.",ar:"**بكمرات طرفية (Marginal beams)** — كمرات على الأطراف بس: بتشيل حوائط الواجهة وبتجسّئ الأحرف الحرة."}]},{t:"note",tone:"info",text:{en:"A drop panel is **part of the slab** (it widens the column strip and adds to the load); a column head is **part of the column** (it enlarges the punching perimeter and the column size in the moment formula, but not the strips).",ar:"السقوط **جزء من البلاطة** (بيعرّض شريحة العمود وبيزوّد الحمل)؛ أما تاج العمود فهو **جزء من العمود** (بيكبّر محيط القص الثاقب ومقاس العمود في معادلة العزم، مش الشرائح)."}},{t:"quiz",q:{kind:"mcq",q:{en:"Which of these is counted as part of the column, not of the slab?",ar:"أنهي واحد من دول بيتحسب جزء من العمود مش من البلاطة؟"},options:[{en:"The drop panel",ar:"السقوط"},{en:"The column head",ar:"تاج العمود"},{en:"The marginal beam",ar:"الكمرة الطرفية"}],answer:1,explain:{en:"The head belongs to the column: it changes the punching perimeter and D in M_o. The drop panel belongs to the slab and sets the column-strip width.",ar:"التاج تبع العمود: بيغيّر محيط القص الثاقب و D في M_o. أما السقوط فتبع البلاطة وبيحدد عرض شريحة العمود."}}}]},{id:"strips",title:{en:"How it carries its load: column strips and field strips",ar:"بتشيل حملها إزاي: شرائح الأعمدة والشرائح الوسطى"},blocks:[{t:"p",text:{en:"Picture the floor as two families of crossing strips. A strip that runs over the columns — a **column strip** (شريحة العمود) — rests on supports that do not move, like a continuous beam on columns. A strip through the middle of the panels — a **field strip** (الشريحة الوسطى) — has no column under it: it rests on the column strips that cross it, and those sag. A support that sinks attracts less moment, so the **column strips carry most of the moment**, and the slab deflects like a dish between four columns, deepest at the panel centre.",ar:"تخيّل الدور عيلتين من الشرائح المتقاطعة. الشريحة اللي ماشية فوق الأعمدة — **شريحة العمود** — قاعدة على ركائز مابتتحركش، زي كمرة مستمرة على أعمدة. أما الشريحة اللي ماشية في نص البواكي — **الشريحة الوسطى** — فمفيش تحتها عمود: قاعدة على شرائح الأعمدة اللي بتقطعها، ودي بترخّم. والركيزة اللي بتهبط بتشد عزم أقل، فـ**شرائح الأعمدة بتشيل معظم العزم**، والبلاطة بترخّم زي طبق بين أربع أعمدة، وأعمق نقطة في نص الباكية."}},{t:"eq",tex:["b_{CS} = \\dfrac{L_2}{2},\\qquad b_{FS} = B - b_{CS}"],caption:{en:"L2: the shorter side of the panel — the same column-strip width in both directions, L2/4 on each side of the column line. B: the panel width across the strips (centre line to centre line). With drop panels b_CS = X; along a free edge the column strip is only L2/4.",ar:"L2: الضلع الأقصر للباكية — نفس عرض شريحة العمود في الاتجاهين، L2/4 من كل ناحية من خط الأعمدة. B: عرض الباكية العمودي على الشرائح (من محور لمحور). مع السقوط b_CS = X؛ وعلى الحرف الحر شريحة العمود L2/4 بس."}},{t:"p",text:{en:"**The office floor of this episode:** 4 × 3 bays of 6.4 m (x) × 5.6 m (y), a storey height of 3.6 m, 400 × 400 columns, fcu = 30 and fy = 400 N/mm², F.C. = 1.5, walls 1.5 and L.L. = 3.0 kN/m². Here $L_2 = 5.6$ m, so $b_{CS} = 2.8$ m both ways. The strips spanning x are 5.6 m apart: $b_{FS} = 5.6 - 2.8 = 2.8$ m — equal strips. The strips spanning y are 6.4 m apart: $b_{FS} = 6.4 - 2.8 = 3.6$ m — the field strip is wider, which we will have to correct for.",ar:"**دور المكاتب بتاع الحلقة دي:** 4 × 3 بواكي 6.4 م (x) × 5.6 م (y)، وارتفاع الدور 3.6 م، وأعمدة 400 × 400، و fcu = 30 و fy = 400 N/mm²، والتشطيبات 1.5 والحوائط 1.5 والحمل الحي 3.0 kN/m². هنا $L_2 = 5.6$ م، يبقى $b_{CS} = 2.8$ م في الاتجاهين. الشرائح اللي بتشيل في x المسافة بينها 5.6 م: $b_{FS} = 5.6 - 2.8 = 2.8$ م — شرائح متساوية. والشرائح اللي بتشيل في y المسافة بينها 6.4 م: $b_{FS} = 6.4 - 2.8 = 3.6$ م — الشريحة الوسطى أعرض، وده هنحتاج نصلّحه بعدين."}},{t:"lab",lab:"flatslab",height:480,props:{preset:"default",missions:t,defaultTab:"results"},caption:{en:"The office floor on its 400 × 400 columns: tint the strips, switch between x and y, click a panel — and notice the red punching cone and the red critical perimeters of the interior columns (the next steps deal with them).",ar:"دور المكاتب على أعمدة 400 × 400: لوّن الشرائح، وبدّل بين x و y، واضغط على باكية — وخلّي بالك من مخروط القص الثاقب الأحمر والمحيطات الحرجة الحمرا حوالين الأعمدة الداخلية (الخطوات الجاية هتتعامل معاها)."}},{t:"quiz",q:{kind:"num",q:{en:"A panel 7.0 × 5.0 m without drop panels. Width of the field strip among the strips that span the 5.0 m direction (m)?",ar:"باكية 7.0 × 5.0 م من غير سقوط. عرض الشريحة الوسطى في الشرائح اللي بتشيل في اتجاه الـ 5.0 م (م)؟"},answer:4.5,tol:.001,unit:"m",explain:{en:"Column strip $5.0/2 = 2.5$ m; those strips sit 7.0 m apart, so the field strip is $7.0 - 2.5 = 4.5$ m.",ar:"شريحة العمود $5.0/2 = 2.5$ م؛ والشرائح دي المسافة بينها 7.0 م، يبقى الشريحة الوسطى $7.0 - 2.5 = 4.5$ م."}}}]},{id:"dims",title:{en:"Concrete dimensions: columns, thickness and cover",ar:"الأبعاد الخرسانية: الأعمدة والتخانة والغطاء"},blocks:[{t:"p",text:{en:"A flat-slab column must resist punching, buckling and the unbalanced moments the slab hands it, so it may not be small:",ar:"عمود البلاطة اللاكمرية لازم يقاوم القص الثاقب والانبعاج والعزوم غير المتوازنة اللي البلاطة بتسلّمهاله، فمينفعش يبقى صغير:"}},{t:"eq",tex:["b_{min} = \\max\\left(300,\\ \\dfrac{H}{15},\\ \\dfrac{L_1}{20}\\right)"],caption:{en:"Rounded up to 50 mm; H = column height, L1 = the longer span; for circular columns this is the diameter.",ar:"بيتقرّب لأعلى لـ 50 مم؛ H = ارتفاع العمود، و L1 = البحر الأطول؛ وفي الأعمدة الدائرية ده القطر."}},{t:"table",head:[{en:"Panel",ar:"الباكية"},{en:"without drop panels",ar:"من غير سقوط"},{en:"with drop panels",ar:"بسقوط"}],rows:[[{en:"external",ar:"طرفية"},"$L_1/32$","$L_1/36$"],[{en:"internal",ar:"داخلية"},"$L_1/36$","$L_1/40$"]],caption:{en:"L1 = the longer side of the panel. External: an end bay in the direction of L1 (continuous on one side only); internal: continuous on both sides. Take the largest need; ts ≥ 150 mm, rounded to 150, 160, 180, 200, 220, 240, 250 … mm.",ar:"L1 = الضلع الأطول للباكية. طرفية: باكية طرف في اتجاه L1 (مستمرة من ناحية واحدة)؛ داخلية: مستمرة من الناحيتين. خد أكبر احتياج؛ و ts ≥ 150 مم، والتقريب لـ 150، 160، 180، 200، 220، 240، 250 … مم."}},{t:"p",text:{en:"**Cover and depth.** The bar centres sit about 30 mm from the face: $d = t_s - 30$ for the bars of the long direction, laid first (the «فرش»), and $d = t_s - 40$ for the short-direction bars laid on them (the «غطاء»).",ar:"**الغطاء والعمق.** مراكز الأسياخ بتبقى على بعد حوالي 30 مم من الوش: $d = t_s - 30$ لأسياخ الاتجاه الطويل اللي بتتحط الأول (الفرش)، و $d = t_s - 40$ لأسياخ الاتجاه القصير اللي بتترص فوقها (الغطاء)."}},{t:"p",text:{en:"**Example — the office floor.** $b_{min} = \\max(300,\\ 3600/15,\\ 6400/20) = \\max(300,\\ 240,\\ 320) = 320$ → **350 mm**, so the 400 × 400 columns are fine. Every panel is 6.4 × 5.6 m with $L_1 = 6.4$ m along x; the end bays in x are external: $6400/32 = 200$ mm; the interior bays $6400/36 = 177.8$ mm → **$t_s = 200$ mm**, $d = 170$ mm along x and 160 mm along y. With drop panels it would be $6400/36 = 177.8$ and $6400/40 = 160$ → 180 mm. **A second floor** with x-spans 6.0 / 6.6 / 6.6 / 6.0 m and y-spans 5.4 / 5.8 / 5.4 m: the 6.6 m panels are internal in x, $6600/36 = 183.3$ mm, but the shorter end panels are external, $6000/32 = 187.5$ mm → they govern: 200 mm.",ar:"**مثال — دور المكاتب.** $b_{min} = \\max(300,\\ 3600/15,\\ 6400/20) = \\max(300,\\ 240,\\ 320) = 320$ ← **350 مم**، يعني الأعمدة 400 × 400 تمام. كل باكية 6.4 × 5.6 م و $L_1 = 6.4$ م على x؛ وبواكي الطرف في x طرفية: $6400/32 = 200$ مم؛ والبواكي الداخلية $6400/36 = 177.8$ مم ← **$t_s = 200$ مم**، و $d = 170$ مم على x و 160 مم على y. ولو بسقوط كانت هتبقى $6400/36 = 177.8$ و $6400/40 = 160$ ← 180 مم. **دور تاني** بحوره على x هي 6.0 / 6.6 / 6.6 / 6.0 م وعلى y هي 5.4 / 5.8 / 5.4 م: بواكي الـ 6.6 م داخلية في x، $6600/36 = 183.3$ مم، بس بواكي الطرف الأقصر طرفية، $6000/32 = 187.5$ مم ← هي اللي بتحكم: 200 مم."}},{t:"quiz",q:{kind:"num",q:{en:"No drop panels: the largest external panel has L1 = 6.8 m, the largest internal one L1 = 7.2 m. ts after rounding (mm)?",ar:"من غير سقوط: أكبر باكية طرفية L1 = 6.8 م، وأكبر باكية داخلية L1 = 7.2 م. قيمة ts بعد التقريب (مم)؟"},answer:220,tol:0,unit:"mm",explain:{en:"$6800/32 = 212.5$ and $7200/36 = 200$: the external panel governs, 212.5 → 220 mm.",ar:"$6800/32 = 212.5$ و $7200/36 = 200$: الباكية الطرفية بتحكم، 212.5 ← 220 مم."}}}]},{id:"drops",title:{en:"Drop panels, column heads and marginal beams",ar:"السقوط وتيجان الأعمدة والكمرات الطرفية"},blocks:[{t:"p",text:{en:"**Drop panels** thicken the slab exactly where the moment hogs and the shear gathers. In each direction they reach $X_i$ from the column centre line; a square drop panel is $X \\times X$:",ar:"**السقوط** بيتخّن البلاطة في نفس المكان اللي العزم فيه سالب والقص بيتجمّع. في كل اتجاه بيوصل لـ $X_i$ من محور العمود؛ والسقوط المربع $X \\times X$:"}},{t:"eq",tex:["\\dfrac{L_{big}}{6} \\le X_i \\le \\dfrac{L_{small}}{4},\\qquad \\dfrac{L_{big}}{3} \\le X \\le \\dfrac{L_{small}}{2},\\qquad t_d \\ge \\dfrac{t_s}{4}"],caption:{en:"In practice X = L_small/2 (half the shorter span) and t_d = t_s/2. The drop panel is part of the slab: the column strip becomes X wide.",ar:"عملياً X = L_small/2 (نص البحر الأقصر) و t_d = t_s/2. والسقوط جزء من البلاطة: شريحة العمود بتبقى بعرض X."}},{t:"eq",tex:["D \\le \\dfrac{L_2}{4},\\qquad \\alpha \\le 45^\\circ,\\qquad D_{eff} = c + 2h"],caption:{en:"Column head of size D, depth h and flare α; a head steeper than 45° counts only inside the 45° lines (D_eff). For a rectangular head the smaller side D2 obeys the L2/4 limit.",ar:"تاج بمقاس D وعمق h وميل α؛ والتاج الأميل من 45° بيتحسب جوه خطوط الـ 45° بس (D_eff). وفي التاج المستطيل الضلع الأصغر D2 هو اللي بيلتزم بحد L2/4."}},{t:"eq",tex:["t_b \\ge 3\\,t_s,\\qquad w_1 = O.W. + W_{wall} + w_s\\,\\dfrac{L_2}{4},\\qquad w_2 = O.W. + W_{wall} + w_s\\,\\dfrac{L_1}{4}"],caption:{en:"Marginal beam: at least three times the slab thickness; it carries its own weight, the wall on it and a quarter-panel band of slab (w1 for a beam along L1, w2 along L2).",ar:"الكمرة الطرفية: تلات أضعاف تخانة البلاطة على الأقل؛ بتشيل وزنها والحائط اللي عليها وشريط من البلاطة عرضه ربع الباكية (w1 لكمرة على L1، و w2 على L2)."}},{t:"p",text:{en:"**Example — the office floor.** Drop panels: $6.4/3 = 2.13 \\le X \\le 5.6/2 = 2.80$ → **X = 2.8 m**; along x $1.07 \\le 1.40 \\le 1.60$ and along y $0.93 \\le 1.40 \\le 1.40$ ✓; the slab itself may now be 180 mm thick ($L_1/36$) and $t_d = 180/2 = 90$ mm (≥ 45). A head: $D \\le 5.6/4 = 1.4$ m, i.e. 500 mm beyond each face of the 400 mm column; 500 mm deep it flares at 45° ✓, but only 400 mm deep it flares at $\\tan^{-1}(500/400) = 51.3^\\circ > 45^\\circ$ and counts as $D_{eff} = 0.4 + 2\\times0.4 = 1.2$ m. Marginal beams: $t_b \\ge 3\\times200 = 600$ mm; a 250 × 600 beam along x carrying a wall of 8 kN/m (working), with the $w_s = 16.0$ kN/m² of the next step: $1.4\\times0.25\\times0.40\\times25 + 1.4\\times8 + 16.0\\times5.6/4 = 3.5 + 11.2 + 22.4 = 37.1$ kN/m (along y: $3.5 + 11.2 + 16.0\\times6.4/4 = 40.3$ kN/m).",ar:"**مثال — دور المكاتب.** السقوط: $6.4/3 = 2.13 \\le X \\le 5.6/2 = 2.80$ ← **X = 2.8 م**؛ وعلى x $1.07 \\le 1.40 \\le 1.60$ وعلى y $0.93 \\le 1.40 \\le 1.40$ ✓؛ والبلاطة نفسها ممكن تبقى 180 مم ($L_1/36$) و $t_d = 180/2 = 90$ مم (≥ 45). التاج: $D \\le 5.6/4 = 1.4$ م، يعني 500 مم بره كل وش للعمود 400 مم؛ لو عمقه 500 مم ميله 45° ✓، لكن لو عمقه 400 مم بس ميله $\\tan^{-1}(500/400) = 51.3^\\circ > 45^\\circ$ وبيتحسب $D_{eff} = 0.4 + 2\\times0.4 = 1.2$ م. الكمرات الطرفية: $t_b \\ge 3\\times200 = 600$ مم؛ كمرة 250 × 600 على x شايلة حائط 8 kN/m (تشغيل)، وبالـ $w_s = 16.0$ kN/m² بتاعة الخطوة الجاية: $1.4\\times0.25\\times0.40\\times25 + 1.4\\times8 + 16.0\\times5.6/4 = 3.5 + 11.2 + 22.4 = 37.1$ kN/m (وعلى y: $3.5 + 11.2 + 16.0\\times6.4/4 = 40.3$ kN/m)."}},{t:"p",text:{en:"**Reinforcing a column head.** The head belongs to the column: $t_s$, $w_s$, the strips and their moments stay exactly as they are without it — only the punching section moves out to the edge of the head. The column bars run straight up through the head as starters for the column above, while the head gets its own bars that follow its sloping faces and stop in the slab: 1Ø10 in every corner and not more than 300 mm apart. A head of the largest size, $D = L_2/4$ with $\\alpha = 45^\\circ$, needs at least:",ar:"**تسليح تاج العمود.** التاج تبع العمود: $t_s$ و $w_s$ والشرائح وعزومها بيفضلوا زي ما هم من غيره — القطاع الحرج للقص الثاقب بس هو اللي بيتنقل لحرف التاج. أسياخ العمود بتطلع مستقيمة جوه التاج أشاير للعمود اللي فوق، والتاج بياخد أسياخ لوحده ماشية مع أوشه المايلة وبتقف في البلاطة: 1Ø10 في كل ركن، والمسافة بينهم مش أكتر من 300 مم. والتاج بأكبر مقاس، $D = L_2/4$ و $\\alpha = 45^\\circ$، محتاج على الأقل:"}},{t:"eq",tex:["A_{s1} \\ge 0.04\\,A_{s1}^{-}\\,L_2,\\qquad A_{s2} \\ge 0.04\\,A_{s2}^{-}\\,L_1"],caption:{en:"A⁻: the top steel of the column strip over that column in mm²/m — direction 1 along L1, direction 2 along L2. Each direction gets 4 % of its own column-strip steel per metre times the span of the other direction (mm²). A circular head gets As1 + As2 as radial and ring bars.",ar:"A⁻: الحديد العلوي لشريحة العمود فوق العمود ده بالـ mm²/m — الاتجاه 1 على L1 والاتجاه 2 على L2. كل اتجاه بياخد 4 % من حديد المتر بتاع شريحة العمود بتاعته مضروب في بحر الاتجاه التاني (مم²). والتاج الدائري بياخد As1 + As2 أسياخ قطرية وحلقية."}},{t:"p",text:{en:"**Example — a head on a 7.0 × 6.0 m floor.** 500 × 500 columns; over the column the column strips carry 7Ø18/m along the 7.0 m span (1781 mm²/m) and 7Ø16/m along the 6.0 m span (1407 mm²/m). $D = 6.0/4 = 1.5$ m projects 0.5 m beyond each face, so a head 0.5 m deep flares at exactly 45°. $A_{s1} = 0.04\\times1781\\times6.0 = 427.5$ mm² → 6Ø10 (471 mm²); $A_{s2} = 0.04\\times1407\\times7.0 = 394$ mm² → 5Ø10 (393 mm², practically enough). Watch the second line: it takes the 7.0 m span — multiplying by 6.0 again would give only 338 mm².",ar:"**مثال — تاج في دور 7.0 × 6.0 م.** أعمدة 500 × 500؛ وفوق العمود شرائح الأعمدة شايلة 7Ø18 في المتر في اتجاه البحر 7.0 م (1781 مم²/م) و 7Ø16 في المتر في اتجاه البحر 6.0 م (1407 مم²/م). $D = 6.0/4 = 1.5$ م بيطلع 0.5 م بره كل وش، فتاج عمقه 0.5 م ميله 45° بالظبط. $A_{s1} = 0.04\\times1781\\times6.0 = 427.5$ مم² ← 6Ø10 (471 مم²)؛ و $A_{s2} = 0.04\\times1407\\times7.0 = 394$ مم² ← 5Ø10 (393 مم²، كفاية عملياً). خلي بالك من السطر التاني: بياخد البحر 7.0 م — ولو ضربت في 6.0 تاني هيطلع 338 مم² بس."}},{t:"p",text:{en:"**Marginal beams in detail.** An edge beam ties the floor together against wind and earthquakes, stiffens the free edges and carries the façade walls — but only if it is stiff enough to carry the slab instead of hanging on it, hence $t_b \\ge 3\\,t_s$. It is a continuous beam of equal spans loaded by the w of the equation above, and it is also **twisted**: the exterior moments of the strips that end on it — $0.20\\,M_o$ of the column strip and $0.10\\,M_o$ of the field strip — have nowhere else to go.",ar:"**الكمرة الطرفية بالتفصيل.** الكمرة الطرفية بتحزّم الدور ضد الرياح والزلازل، وبتقوّي أطراف البلاطة، وبتشيل حوائط الواجهة — بس بشرط تكون جاسئة كفاية إنها تشيل البلاطة مش تبقى متعلقة فيها، وعشان كده $t_b \\ge 3\\,t_s$. هي كمرة مستمرة ببحور متساوية شايلة الـ w بتاعة المعادلة اللي فوق، وكمان **بتتلوي**: العزوم الخارجية للشرائح اللي بتخلص عندها — $0.20\\,M_o$ من شريحة العمود و $0.10\\,M_o$ من الشريحة الوسطى — مالهاش مكان تاني تروحه."}},{t:"table",head:[{en:"Continuous beam, equal spans",ar:"كمرة مستمرة ببحور متساوية"},{en:"end support",ar:"الركيزة الطرفية"},{en:"end span",ar:"البحر الطرفي"},{en:"first interior support",ar:"أول ركيزة وسطية"},{en:"interior spans",ar:"البحور الوسطية"},{en:"other interior supports",ar:"باقي الركائز الوسطية"}],rows:[[{en:"moment",ar:"العزم"},"$wL^2/24$","$wL^2/12$","$wL^2/10$","$wL^2/16$","$wL^2/12$"],[{en:"shear",ar:"القص"},"$0.45\\,wL$","–","$0.60\\,wL$","–","$0.50\\,wL$"]],caption:{en:"The 0.60 wL is the shear on the outer side of the first interior support.",ar:"الـ 0.60 wL هو القص على الناحية البرانية لأول ركيزة وسطية."}},{t:"eq",tex:["m_t \\approx \\dfrac{(0.20 + 0.10)\\,M_o}{L} = \\dfrac{0.3\\,M_o}{L},\\qquad M_t = 0.5\\,m_t\\,L","t_{ben} = 3.5\\sqrt{\\dfrac{M}{f_{cu}\\,b}},\\qquad t_{tor} \\approx \\dfrac{3\\,M_t}{1.6\\,b^2},\\qquad t = \\max(t_{ben},\\ t_{tor},\\ 3\\,t_s)"],caption:{en:"m_t: torque per metre of beam (kN·m/m), L = the beam span; the torsion diagram runs from +M_t to −M_t along each span. Part of the twist really goes straight into the columns, so this is on the safe side. Bending: an L-section with B = b + 3ts for sagging, a rectangle for hogging; shear and torsion as in the torsion lesson.",ar:"m_t: عزم اللي لكل متر من الكمرة (kN·m/m)، و L = بحر الكمرة؛ ومنحنى عزم اللي بيمشي من +M_t لـ −M_t على طول كل بحر. في الحقيقة جزء من اللي بيروح للأعمدة على طول، فده في ناحية الأمان. الانحناء: قطاع L بـ B = b + 3ts للعزم الموجب ومستطيل للسالب؛ والقص واللي زي درس الالتواء."}},{t:"p",text:{en:"**Example — a marginal beam.** A floor of 3 × 3 bays 7.0 × 6.0 m on 350 × 350 columns, $t_s = 220$ mm, with beams along the two edges where the 7.0 m strips end; fcu 25, fy 350, F.C. 1.5, walls 1.5, L.L. 4.0: $w_s = 18.3$ kN/m² and $M_o = 18.3\\times6.0\\times(7.0 - 0.233)^2/8 = 628.4$ kN·m, so the strips hand the beam $0.20\\,M_o = 125.7$ and $0.10\\,M_o = 62.8$ kN·m. The beam spans 6.0 m; with its own weight taken as 8.0 kN/m, $w = 8.0 + 18.3\\times7.0/4 = 40.0$ kN/m → $wL^2/10 = 144$, $wL^2/12 = 120$, $wL^2/16 = 90$ and $wL^2/24 = 60$ kN·m, shears 108 / 144 / 120 kN. Torsion: $m_t = 0.3\\times628.4/6.0 = 31.42$ kN·m/m → $M_t = 0.5\\times31.42\\times6.0 = 94.3$ kN·m at every support. With $b = 400$: $t_{ben} = 3.5\\sqrt{144\\times10^6/(25\\times400)} = 420$ mm but $t_{tor} = 3\\times94.3\\times10^6/(1.6\\times400^2) = 1105$ mm → **t = 1200 mm**: torsion, not bending (nor $3t_s = 660$), sizes an edge beam.",ar:"**مثال — كمرة طرفية.** دور 3 × 3 بواكي 7.0 × 6.0 م على أعمدة 350 × 350، و $t_s = 220$ مم، وكمرات على الحرفين اللي شرائح الـ 7.0 م بتخلص عندهم؛ و fcu 25، و fy 350، والتشطيبات 1.5، والحوائط 1.5، والحمل الحي 4.0: $w_s = 18.3$ kN/m² و $M_o = 18.3\\times6.0\\times(7.0 - 0.233)^2/8 = 628.4$ kN·m، يعني الشرائح بتسلّم الكمرة $0.20\\,M_o = 125.7$ و $0.10\\,M_o = 62.8$ kN·m. الكمرة بحرها 6.0 م؛ ولو وزنها الذاتي 8.0 kN/m يبقى $w = 8.0 + 18.3\\times7.0/4 = 40.0$ kN/m ← $wL^2/10 = 144$ و $wL^2/12 = 120$ و $wL^2/16 = 90$ و $wL^2/24 = 60$ kN·m، والقص 108 / 144 / 120 kN. اللي: $m_t = 0.3\\times628.4/6.0 = 31.42$ kN·m/m ← $M_t = 0.5\\times31.42\\times6.0 = 94.3$ kN·m عند كل ركيزة. بـ $b = 400$: $t_{ben} = 3.5\\sqrt{144\\times10^6/(25\\times400)} = 420$ مم، لكن $t_{tor} = 3\\times94.3\\times10^6/(1.6\\times400^2) = 1105$ مم ← **t = 1200 مم**: اللي هو اللي بيحدد مقاس الكمرة الطرفية، مش الانحناء (ولا $3t_s = 660$)."}},{t:"p",text:{en:"**Designing it** ($d = 1100$ mm, stirrups fy = 240). Bending: $M = 144$ gives $C_1 = 9.17$ and only 453 mm², so the minimum governs: $\\max(\\min(1414,\\ 1.3\\times453 = 589),\\ 0.15\\%\\times400\\times1100 = 660) = 660$ mm². Shear and torsion at the first interior support: $q_u = 144\\,000/(400\\times1100) = 0.327 < 0.653$ N/mm², so the concrete takes the shear; the stirrup tube has $A_{oh} = 320\\times1120 = 358\\,400$ mm², $A_o = 304\\,640$ mm², $P_h = 2880$ mm and $t_e = 124.4$ mm, so $q_{tu} = 94.3\\times10^6/(2\\times304\\,640\\times124.4) = 1.243$ N/mm² — above $q_{t,min} = 0.06\\sqrt{f_{cu}/\\gamma_c} = 0.245$, so torsion steel is needed — and $\\sqrt{0.327^2 + 1.243^2} = 1.286 < 2.858$ keeps the section. $A_{str}/s = 94.3\\times10^6/(1.7\\times358\\,400\\times208.7) = 0.741$ mm²/mm → Ø10 at 106 mm → **10Ø10/m closed** (100 mm, the smallest spacing used). Longitudinal: $A_{sl} = 0.7854\\times2880\\times240/350 = 1551$ mm², a quarter (388 mm²) on each face: top bars over the support $660 + 388 = 1048$ mm² → 5Ø18, and 4Ø12 on each side face.",ar:"**تصميمها** ($d = 1100$ مم، وحديد الكانات fy = 240). الانحناء: $M = 144$ بيدي $C_1 = 9.17$ و 453 مم² بس، فالحد الأدنى بيحكم: $\\max(\\min(1414,\\ 1.3\\times453 = 589),\\ 0.15\\%\\times400\\times1100 = 660) = 660$ مم². القص واللي عند أول ركيزة وسطية: $q_u = 144\\,000/(400\\times1100) = 0.327 < 0.653$ N/mm²، يعني الخرسانة شايلة القص؛ وأنبوبة الكانات فيها $A_{oh} = 320\\times1120 = 358\\,400$ مم²، و $A_o = 304\\,640$ مم²، و $P_h = 2880$ مم، و $t_e = 124.4$ مم، يبقى $q_{tu} = 94.3\\times10^6/(2\\times304\\,640\\times124.4) = 1.243$ N/mm² — أكبر من $q_{t,min} = 0.06\\sqrt{f_{cu}/\\gamma_c} = 0.245$، يعني محتاجين حديد لي — و $\\sqrt{0.327^2 + 1.243^2} = 1.286 < 2.858$ يعني القطاع كفاية. $A_{str}/s = 94.3\\times10^6/(1.7\\times358\\,400\\times208.7) = 0.741$ مم²/مم ← Ø10 كل 106 مم ← **10Ø10 في المتر كانات مقفلة** (100 مم، أقل تباعد مستخدم). الطولي: $A_{sl} = 0.7854\\times2880\\times240/350 = 1551$ مم²، ربعه (388 مم²) على كل وش: الحديد العلوي فوق الركيزة $660 + 388 = 1048$ مم² ← 5Ø18، و 4Ø12 على كل وش جانبي."}},{t:"quiz",q:{kind:"num",q:{en:"Square drop panels in a floor whose spans lie between 6.0 and 7.2 m. Smallest allowed X (m)?",ar:"سقوط مربع في دور بحوره بين 6.0 و 7.2 م. أصغر X مسموح (م)؟"},answer:2.4,tol:.001,unit:"m",explain:{en:"$X \\ge L_{big}/3 = 7.2/3 = 2.4$ m (and $X \\le 6.0/2 = 3.0$ m).",ar:"$X \\ge L_{big}/3 = 7.2/3 = 2.4$ م (و $X \\le 6.0/2 = 3.0$ م)."}}}]},{id:"loads",title:{en:"Loads on a flat slab",ar:"الأحمال على البلاطة اللاكمرية"},blocks:[{t:"eq",tex:["w_s = 1.4\\,(t_s\\,\\gamma_c + F.C. + W) + 1.6\\,L.L."],caption:{en:"W: the walls, taken as a uniform load of 1.5–2.0 kN/m² (working) — there are no beams to carry them, unlike a solid slab.",ar:"W: الحوائط، بتتاخد كحمل موزع منتظم 1.5–2.0 kN/m² (تشغيل) — مفيش كمرات تشيلها، على عكس البلاطة المصمتة."}},{t:"eq",tex:["t_{s,av} = t_s + t_d\\,\\dfrac{X^2}{L_1\\,L_2} \\approx t_s + \\dfrac{t_d}{4}"],caption:{en:"With drop panels the average thickness replaces ts in the own weight: every panel holds four quarters of a drop panel.",ar:"مع السقوط التخانة المتوسطة بتحل محل ts في الوزن الذاتي: كل باكية فيها أربع أرباع سقوط."}},{t:"p",text:{en:"**Example — the office floor.** $g_s = 0.20\\times25 + 1.5 + 1.5 = 8.0$ kN/m² and $w_s = 1.4\\times8.0 + 1.6\\times3.0 = 11.2 + 4.8 = 16.0$ kN/m². With the drop panels: $t_{s,av} = 180 + 90\\times2.8^2/(6.4\\times5.6) = 199.7$ mm (the short form gives $180 + 90/4 = 202.5$), $g_s = 7.99$ and $w_s = 15.99$ kN/m² — the drops cost almost nothing, because the slab between them became 20 mm thinner.",ar:"**مثال — دور المكاتب.** $g_s = 0.20\\times25 + 1.5 + 1.5 = 8.0$ kN/m² و $w_s = 1.4\\times8.0 + 1.6\\times3.0 = 11.2 + 4.8 = 16.0$ kN/m². ومع السقوط: $t_{s,av} = 180 + 90\\times2.8^2/(6.4\\times5.6) = 199.7$ مم (والصيغة المختصرة بتدي $180 + 90/4 = 202.5$)، و $g_s = 7.99$ و $w_s = 15.99$ kN/m² — السقوط تقريباً مالوش تمن، لأن البلاطة اللي بينه بقت أرفع بـ 20 مم."}},{t:"note",tone:"code",text:{en:"When the live load is not more than 0.75 of the dead load the code also accepts $U = 1.5\\,(D + L)$ — your building has used it since the first RC episode.",ar:"لما الحمل الحي مايزيدش عن 0.75 من الحمل الميت الكود بيقبل كمان $U = 1.5\\,(D + L)$ — ومبناك ماشي بيه من أول حلقة خرسانة."}},{t:"quiz",q:{kind:"num",q:{en:"ts = 200 mm with drop panels 3.0 × 3.0 m, td = 100 mm, on 6.0 × 6.0 m panels. ts,av (mm)?",ar:"ts = 200 مم وسقوط 3.0 × 3.0 م و td = 100 مم على بواكي 6.0 × 6.0 م. قيمة ts,av (مم)؟"},answer:225,tol:.001,unit:"mm",explain:{en:"$200 + 100\\times3.0^2/(6.0\\times6.0) = 200 + 25 = 225$ mm — here exactly $t_s + t_d/4$ because X = L/2.",ar:"$200 + 100\\times3.0^2/(6.0\\times6.0) = 200 + 25 = 225$ مم — وهنا بالظبط $t_s + t_d/4$ لأن X = L/2."}}}]},{id:"punching",title:{en:"Punching shear I: the critical section around a column",ar:"القص الثاقب ١: القطاع الحرج حوالين العمود"},blocks:[{t:"p",text:{en:"All the load of a panel ends in a small area around each column. If the shear stress there is too high, the slab **punches**: a truncated cone (a pyramid for square columns) of concrete, its sides at about 45°, stays on the column while the slab around it drops — suddenly, without the warning cracks of bending. The code checks a **critical section** at d/2 from the column face (or from the head, or from the drop-panel edge); its length is the **critical perimeter** $b_o$ (المحيط الحرج).",ar:"حمل الباكية كله بيخلص في مساحة صغيرة حوالين كل عمود. لو إجهاد القص هناك عالي زيادة، البلاطة **بتتخرم**: مخروط ناقص (هرم لو العمود مربع) من الخرسانة، جوانبه بميل حوالي 45°، بيفضل على العمود والبلاطة اللي حواليه بتنزل — فجأة، من غير شروخ الانحناء اللي بتنذر. الكود بيراجع **قطاع حرج** على بعد d/2 من وش العمود (أو من التاج، أو من حرف السقوط)؛ وطوله هو **المحيط الحرج** $b_o$."}},{t:"eq",tex:["q_{up} = \\dfrac{\\beta\\,Q_{up}}{b_o\\,d}"],caption:{en:"β = 1.15 interior, 1.30 edge, 1.50 corner: the unbalanced moment raises the stress on one side of the perimeter. Q_up = the load of the tributary area minus the load inside the critical section.",ar:"β = 1.15 داخلي، و 1.30 طرفي، و 1.50 ركني: العزم غير المتوازن بيزوّد الإجهاد على ناحية من المحيط. Q_up = حمل مساحة التحميل ناقص الحمل اللي جوه القطاع الحرج."}},{t:"table",head:[{en:"Column",ar:"العمود"},"$Q_{up}$","$b_o$"],rows:[[{en:"interior",ar:"داخلي"},"$w_s[L_1L_2 - (c_1+d)(c_2+d)]$","$2(c_1+d) + 2(c_2+d)$"],[{en:"edge",ar:"طرفي"},"$w_s[\\tfrac{1}{2}L_1L_2 - (c_1+d)(c_2+\\tfrac{d}{2})]$","$(c_1+d) + 2(c_2+\\tfrac{d}{2})$"],[{en:"corner",ar:"ركني"},"$w_s[\\tfrac{L_1}{2}\\tfrac{L_2}{2} - (c_1+\\tfrac{d}{2})(c_2+\\tfrac{d}{2})]$","$(c_1+\\tfrac{d}{2}) + (c_2+\\tfrac{d}{2})$"],[{en:"circular, interior",ar:"دائري، داخلي"},"$w_s[L_1L_2 - \\pi(D+d)^2/4]$","$\\pi(D+d)$"]],caption:{en:'L1 × L2: the tributary area, from panel centre line to centre line. For an edge column c1 runs along the free edge. With a head use its size; with a drop panel check again with the drop panel as the "column" and d = ts − cover.',ar:"L1 × L2: مساحة التحميل من محور الباكية لمحورها. في العمود الطرفي c1 على طول الحرف الحر. مع التاج استخدم مقاسه؛ ومع السقوط راجع تاني والسقوط هو «العمود» و d = ts − الغطاء."}},{t:"p",text:{en:"**Example — the office floor** ($w_s = 16.0$, $d = 170$ mm). Interior column 400 × 400: $A = 6.4\\times5.6 = 35.84$ m², $Q_{up} = 16.0\\times(35.84 - 0.57^2) = 568.2$ kN, $b_o = 4\\times570 = 2280$ mm and $q_{up} = 1.15\\times568.2\\times10^3/(2280\\times170) = 1.686$ N/mm². Edge column (free edge along x): $Q_{up} = 16.0\\times(17.92 - 0.57\\times0.485) = 282.3$ kN, $b_o = 570 + 2\\times485 = 1540$ mm, $q_{up} = 1.402$. Corner column: $Q_{up} = 16.0\\times(8.96 - 0.485^2) = 139.6$ kN, $b_o = 970$ mm, $q_{up} = 1.270$. A circular interior column of 450 mm would give $b_o = \\pi\\times620 = 1948$ mm and $q_{up} = 1.975$ N/mm².",ar:"**مثال — دور المكاتب** ($w_s = 16.0$، و $d = 170$ مم). عمود داخلي 400 × 400: $A = 6.4\\times5.6 = 35.84$ م²، و $Q_{up} = 16.0\\times(35.84 - 0.57^2) = 568.2$ kN، و $b_o = 4\\times570 = 2280$ مم، و $q_{up} = 1.15\\times568.2\\times10^3/(2280\\times170) = 1.686$ N/mm². عمود طرفي (الحرف الحر على x): $Q_{up} = 16.0\\times(17.92 - 0.57\\times0.485) = 282.3$ kN، و $b_o = 570 + 2\\times485 = 1540$ مم، و $q_{up} = 1.402$. عمود ركني: $Q_{up} = 16.0\\times(8.96 - 0.485^2) = 139.6$ kN، و $b_o = 970$ مم، و $q_{up} = 1.270$. ولو عمود داخلي دائري 450 مم هيدي $b_o = \\pi\\times620 = 1948$ مم و $q_{up} = 1.975$ N/mm²."}},{t:"p",text:{en:"**Tributary areas next to a cantilever.** A column’s area runs from panel centre line to centre line — except towards a cantilever: a column at the root of a cantilever carries the whole cantilever out to the free edge. With a 2.0 m cantilever and 6.0 m spans its area is $2.0 + 3.0 = 5.0$ m deep in that direction instead of 6.0 m. A quick hand check often looks only at the most loaded column; on a real floor check every column and thicken (drop panels) only where punching fails.",ar:"**مساحة التحميل جنب الكابولي.** مساحة العمود بتتاخد من محور الباكية لمحورها — إلا ناحية الكابولي: العمود اللي عند جذر الكابولي بيشيل الكابولي كله لحد الحرف الحر. لو الكابولي 2.0 م والبحور 6.0 م، مساحته عمقها في الاتجاه ده $2.0 + 3.0 = 5.0$ م بدل 6.0 م. المراجعة السريعة باليد غالباً بتبص على أكتر عمود محمّل بس؛ لكن في الدور الحقيقي راجع كل الأعمدة، وتخّن (بالسقوط) بس مكان ما القص الثاقب يفشل."}},{t:"lab",lab:"flatslab",height:480,props:{preset:"default",missions:a,defaultTab:"punching"},caption:{en:"The office floor again, with the Punching tab open: pick columns, watch the critical perimeter and the four limits, then save the floor.",ar:"دور المكاتب تاني وتبويب القص الثاقب مفتوح: اختار أعمدة، وتابع المحيط الحرج والحدود الأربعة، وبعدين أنقذ الدور."}},{t:"quiz",q:{kind:"num",q:{en:"Interior column 500 × 500 mm, d = 180 mm. b_o (mm)?",ar:"عمود داخلي 500 × 500 مم، و d = 180 مم. قيمة b_o (مم)؟"},answer:2720,tol:0,unit:"mm",explain:{en:"$b_o = 4\\times(500 + 180) = 2720$ mm.",ar:"$b_o = 4\\times(500 + 180) = 2720$ مم."}}}]},{id:"limits",title:{en:"Punching shear II: the allowable stress, and what to do when it fails",ar:"القص الثاقب ٢: الإجهاد المسموح، ونعمل إيه لو مش آمن"},blocks:[{t:"eq",tex:["q_{cup} = \\min\\left\\{0.8\\left(\\dfrac{\\alpha\\,d}{b_o} + 0.2\\right)\\sqrt{\\dfrac{f_{cu}}{\\gamma_c}},\\ 0.316\\left(0.5 + \\dfrac{a}{b}\\right)\\sqrt{\\dfrac{f_{cu}}{\\gamma_c}},\\ 0.316\\sqrt{\\dfrac{f_{cu}}{\\gamma_c}},\\ 1.70\\right\\}"],caption:{en:"α = 4 interior, 3 edge, 2 corner; a/b = shorter/longer side of the column (of the effective loaded area for irregular columns). q_up ≤ q_cup: the concrete alone is enough.",ar:"α = 4 داخلي، و 3 طرفي، و 2 ركني؛ و a/b = الضلع الأقصر/الأطول للعمود (لمساحة التحميل الفعالة في الأعمدة غير المنتظمة). لو q_up ≤ q_cup: الخرسانة لوحدها كفاية."}},{t:"p",text:{en:"**Example — the office floor**, fcu = 30: $\\sqrt{30/1.5} = 4.472$. Interior column: $0.8\\times(4\\times170/2280 + 0.2)\\times4.472 = 1.783$, $0.316\\times1.5\\times4.472 = 2.120$, $0.316\\times4.472 = 1.413$ and 1.70 → $q_{cup} = 1.413 < 1.686$ ✗. The edge (1.402) and corner (1.270) columns pass; the six interior columns punch. What can be done:",ar:"**مثال — دور المكاتب**، و fcu = 30: $\\sqrt{30/1.5} = 4.472$. العمود الداخلي: $0.8\\times(4\\times170/2280 + 0.2)\\times4.472 = 1.783$، و $0.316\\times1.5\\times4.472 = 2.120$، و $0.316\\times4.472 = 1.413$، و 1.70 ← $q_{cup} = 1.413 < 1.686$ ✗. الأعمدة الطرفية (1.402) والركنية (1.270) بتعدّي؛ والست أعمدة الداخلية بيتخرموا. نعمل إيه:"}},{t:"steps",items:[{en:"**A bigger column** — 600 × 600: $Q_{up} = 564.0$ kN, $b_o = 3080$ mm → $q_{up} = 1.239$ ✓.",ar:"**عمود أكبر** — 600 × 600: $Q_{up} = 564.0$ kN، و $b_o = 3080$ مم ← $q_{up} = 1.239$ ✓."},{en:"**A thicker slab** — 240 mm: $w_s = 17.4$, $d = 210$ → $q_{up} = 1.385$ ✓, just — and heavy everywhere.",ar:"**بلاطة أتخن** — 240 مم: $w_s = 17.4$، و $d = 210$ ← $q_{up} = 1.385$ ✓، بالعافية — وتقيلة في كل حتة."},{en:"**Drop panels** 2.8 × 2.8 m × 90 mm on a 180 mm slab: at the column $d_1 = 180 + 90 - 30 = 240$ mm → $q_{up} = 1.060$ ✓; at d/2 outside the drop panel ($d = 150$): $Q_{up} = 433.9$ kN, $b_o = 4\\times2950 = 11\\,800$ mm → $q_{up} = 0.282$ ✓. Both sections must pass.",ar:"**سقوط** 2.8 × 2.8 م × 90 مم على بلاطة 180 مم: عند العمود $d_1 = 180 + 90 - 30 = 240$ مم ← $q_{up} = 1.060$ ✓؛ وعلى بعد d/2 بره السقوط ($d = 150$): $Q_{up} = 433.9$ kN، و $b_o = 4\\times2950 = 11\\,800$ مم ← $q_{up} = 0.282$ ✓. القطاعين لازم يعدّوا."},{en:"**Column heads** of 1.4 m: $b_o = 4\\times1570 = 6280$ mm → $q_{up} = 0.575$ ✓ (the first limit, 1.103, governs now); a 1.2 m effective head still gives 0.671 ✓.",ar:"**تيجان للأعمدة** 1.4 م: $b_o = 4\\times1570 = 6280$ مم ← $q_{up} = 0.575$ ✓ (الحد الأول، 1.103، هو اللي بيحكم دلوقتي)؛ وتاج فعال 1.2 م بيدي 0.671 ✓ برضه."},{en:"**Shear stirrups** (كانات) — allowed only when the slab is at least 250 mm thick; they can lift the stress up to $0.45\\sqrt{f_{cu}/\\gamma_c}$.",ar:"**كانات للقص** — مسموحة بس لو البلاطة 250 مم أو أتخن؛ وبتقدر ترفع الإجهاد لحد $0.45\\sqrt{f_{cu}/\\gamma_c}$."}]},{t:"eq",tex:["q_{up} \\le q_{cup,cr} + \\dfrac{n\\,A_s\\,(f_y/\\gamma_s)}{b_o\\,S} \\le 0.45\\sqrt{\\dfrac{f_{cu}}{\\gamma_c}},\\qquad q_{cup,cr} = 0.12\\sqrt{\\dfrac{f_{cu}}{\\gamma_c}}"],caption:{en:"n legs of area As in every ring around the column, rings S ≤ d/2 apart, stirrup steel fy = 240 or 350. Then check again, with concrete only, d/2 beyond the last ring.",ar:"n فرع مساحته As في كل حلقة حوالين العمود، والحلقات كل S ≤ d/2، وحديد الكانات fy = 240 أو 350. وبعدين راجع تاني بالخرسانة بس على بعد d/2 بعد آخر حلقة."}},{t:"p",text:{en:"**Example — a store on the same grid**, $t_s = 250$ mm, L.L. = 6 kN/m²: $w_s = 22.55$, $d = 220$ → $q_{up} = 1.685 > 1.413$ but $\\le 0.45\\times4.472 = 2.012$, so stirrups can work. $q_{cup,cr} = 0.12\\times4.472 = 0.537$; with 16 legs Ø10 (fy = 240) per ring: $S = 16\\times78.5\\times208.7/(2480\\times(1.685 - 0.537)) = 92$ → **90 mm** ≤ d/2 = 110 ✓. A concrete-only section d/2 beyond a ring 100 mm from the face already passes ($q_{up} = 1.264$), so two rings are enough.",ar:"**مثال — مخزن على نفس الشبكة**، و $t_s = 250$ مم، والحمل الحي 6 kN/m²: $w_s = 22.55$، و $d = 220$ ← $q_{up} = 1.685 > 1.413$ لكن $\\le 0.45\\times4.472 = 2.012$، يعني الكانات ممكن تنفع. $q_{cup,cr} = 0.12\\times4.472 = 0.537$؛ وبـ 16 فرع Ø10 (fy = 240) في الحلقة: $S = 16\\times78.5\\times208.7/(2480\\times(1.685 - 0.537)) = 92$ ← **90 مم** ≤ d/2 = 110 ✓. وقطاع خرسانة بس على بعد d/2 بعد حلقة على 100 مم من الوش بيعدّي أصلاً ($q_{up} = 1.264$)، يعني حلقتين كفاية."}},{t:"steps",items:[{en:"**Near a slab edge:** a column whose distance Y to the edge is not more than (b + d)/2 is checked with the edge-column section.",ar:"**جنب حرف البلاطة:** العمود اللي بعده Y عن الحرف مش أكتر من (b + d)/2 بيتراجع بقطاع العمود الطرفي."},{en:"**Voids (فتحات) inside the critical area:** draw lines from the column centre to the edges of the void; the part of $b_o$ between them does not count. A 400 mm void whose near face is 1.0 m from the centre, facing a perimeter side 285 mm from the centre, removes $400\\times285/1000 = 114$ mm.",ar:"**فتحات جوه المساحة الحرجة:** ارسم خطوط من مركز العمود لأحرف الفتحة؛ وجزء $b_o$ اللي بينهم مايتحسبش. فتحة 400 مم وشها القريب على بعد 1.0 م من المركز، قصاد ضلع محيط على بعد 285 مم من المركز، بتشيل $400\\times285/1000 = 114$ مم."},{en:"**L-shaped or irregular columns:** use the effective loaded area (the rectangle that the column really pushes) and its a/b.",ar:"**الأعمدة على شكل L أو غير المنتظمة:** استخدم مساحة التحميل الفعالة (المستطيل اللي العمود بيزقه فعلاً) ونسبة a/b بتاعتها."}]},{t:"p",text:{en:"**Example — a floor with a cantilever edge.** Spans 6.5 / 7.0 / 6.5 m along x; along y a 2.0 m cantilever and three 6.0 m spans; storey 3.5 m, fcu 30, fy 400, F.C. 2.0, walls 2.0, L.L. 3.0. Columns $\\max(300,\\ 233,\\ 350) = 350$ mm; $t_s = \\max(6500/32,\\ 7000/36) = \\max(203.1,\\ 194.4)$ → 220 mm; $w_s = 1.4\\times(5.5 + 2.0 + 2.0) + 1.6\\times3.0 = 18.1$ kN/m². An interior column (area $6.75\\times6.0$ m, $d = 190$): $Q_{up} = 18.1\\times(40.5 - 0.54^2) = 727.8$ kN and $q_{up} = 1.15\\times727\\,800/(2160\\times190) = 2.04$ N/mm², far above $q_{cup} = \\min(1.97,\\ 2.12,\\ 1.41,\\ 1.70) = 1.41$ ✗.",ar:"**مثال — دور بحرف كابولي.** البحور 6.5 / 7.0 / 6.5 م على x؛ وعلى y كابولي 2.0 م وتلات بحور 6.0 م؛ وارتفاع الدور 3.5 م، و fcu 30، و fy 400، والتشطيبات 2.0، والحوائط 2.0، والحمل الحي 3.0. الأعمدة $\\max(300,\\ 233,\\ 350) = 350$ مم؛ و $t_s = \\max(6500/32,\\ 7000/36) = \\max(203.1,\\ 194.4)$ ← 220 مم؛ و $w_s = 1.4\\times(5.5 + 2.0 + 2.0) + 1.6\\times3.0 = 18.1$ kN/m². عمود داخلي (مساحته $6.75\\times6.0$ م، و $d = 190$): $Q_{up} = 18.1\\times(40.5 - 0.54^2) = 727.8$ kN و $q_{up} = 1.15\\times727\\,800/(2160\\times190) = 2.04$ N/mm²، أكبر بكتير من $q_{cup} = \\min(1.97,\\ 2.12,\\ 1.41,\\ 1.70) = 1.41$ ✗."}},{t:"p",text:{en:"**The fix: drop panels** $X = 6.0/2 = 3.0$ m square. They change the thickness rule too: $\\max(6500/36,\\ 7000/40) = \\max(180.6,\\ 175)$ → $t_s = 200$ mm, $t_d = 100$ mm, $t_{s,av} = 200 + 100/4 = 225$ mm and $w_s = 1.4\\times(5.625 + 4.0) + 4.8 = 18.275$ kN/m². **Check 1**, at d1/2 from the column face with $d_1 = 200 + 100 - 30 = 270$: $Q_{up} = 18.275\\times(40.5 - 0.62^2) = 733.1$ kN on $b_o\\,d = 2480\\times270 = 669\\,600$ mm² → $q_{up} = 1.26 < 1.41$ ✓. **Check 2**, at d/2 outside the drop panel with $d = 200 - 30 = 170$: the section is a square of $X + d = 3.17$ m, $Q_{up} = 18.275\\times(40.5 - 3.17^2) = 556.5$ kN on $12\\,680\\times170 = 2\\,155\\,600$ mm² → $q_{up} = 0.297$ ✓.",ar:"**الحل: سقوط** مربع $X = 6.0/2 = 3.0$ م. السقوط بيغيّر قاعدة التخانة كمان: $\\max(6500/36,\\ 7000/40) = \\max(180.6,\\ 175)$ ← $t_s = 200$ مم، و $t_d = 100$ مم، و $t_{s,av} = 200 + 100/4 = 225$ مم، و $w_s = 1.4\\times(5.625 + 4.0) + 4.8 = 18.275$ kN/m². **المراجعة 1** على بعد d1/2 من وش العمود و $d_1 = 200 + 100 - 30 = 270$: $Q_{up} = 18.275\\times(40.5 - 0.62^2) = 733.1$ kN على $b_o\\,d = 2480\\times270 = 669\\,600$ مم² ← $q_{up} = 1.26 < 1.41$ ✓. **المراجعة 2** على بعد d/2 بره السقوط و $d = 200 - 30 = 170$: القطاع مربع ضلعه $X + d = 3.17$ م، و $Q_{up} = 18.275\\times(40.5 - 3.17^2) = 556.5$ kN على $12\\,680\\times170 = 2\\,155\\,600$ مم² ← $q_{up} = 0.297$ ✓."}},{t:"p",text:{en:"**A column at a re-entrant corner** (a slab with a corner cut away, e.g. around a ramp) has slab on three quarters of its perimeter: $Q_{up} = w_s\\,[L_1L_2 - ((c + d)^2 - (d/2)^2) - A_{cut}]$ plus any reactions it carries, $b_o = 2(c + d) + 2(c + d/2)$, and β lies between the interior and the corner values — take 1.50.",ar:"**عمود عند ركن داخلي** (بلاطة مقطوع منها ركن، زي حوالين رامب) البلاطة حواليه في تلات أرباع محيطه: $Q_{up} = w_s\\,[L_1L_2 - ((c + d)^2 - (d/2)^2) - A_{cut}]$ زائد أي ردود أفعال شايلها، و $b_o = 2(c + d) + 2(c + d/2)$، و β بين قيمة العمود الداخلي والركني — خد 1.50."}},{t:"quiz",q:{kind:"num",q:{en:"fcu = 25, interior 400 × 400 column, d = 170 mm, b_o = 2280 mm. q_cup (N/mm²)?",ar:"fcu = 25، وعمود داخلي 400 × 400، و d = 170 مم، و b_o = 2280 مم. قيمة q_cup (N/mm²)؟"},answer:1.29,tol:.005,unit:"N/mm²",explain:{en:"$\\sqrt{25/1.5} = 4.082$: limits 1.627, 1.935, $0.316\\times4.082 = 1.290$ and 1.70 → 1.29.",ar:"$\\sqrt{25/1.5} = 4.082$: الحدود 1.627 و 1.935 و $0.316\\times4.082 = 1.290$ و 1.70 ← 1.29."}}}]},{id:"empirical",title:{en:"The empirical method: M_o and its strips",ar:"الطريقة التقريبية: M_o والشرائح"},blocks:[{t:"p",text:{en:"The **empirical method** (الطريقة التقريبية) takes the total moment of a panel and shares it out with a table — no analysis. It is allowed only for regular floors:",ar:"**الطريقة التقريبية** بتاخد العزم الكلي للباكية وبتوزعه بجدول — من غير تحليل. ومسموحة بس للأدوار المنتظمة:"}},{t:"steps",items:[{en:"at least three bays in each direction;",ar:"تلات بواكي على الأقل في كل اتجاه؛"},{en:"panels not longer than 1.30 times their width ($L_1/L_2 \\le 1.30$);",ar:"الباكية مش أطول من 1.30 مرة عرضها ($L_1/L_2 \\le 1.30$)؛"},{en:"adjacent spans differ by no more than 10 % of the larger, any two by no more than 20 %; end spans not longer than the interior ones; where spans differ, use the larger;",ar:"البحور المتجاورة مختلفة بما لا يزيد عن 10 % من الأكبر، وأي بحرين بما لا يزيد عن 20 %؛ والبحور الطرفية مش أطول من الداخلية؛ ولو البحور مختلفة خد الأكبر؛"},{en:"columns in line (offset ≤ 10 % of the span);",ar:"الأعمدة على استقامة واحدة (الانحراف ≤ 10 % من البحر)؛"},{en:"L.L. ≤ 2 D.L. (D.L. = ts γc + F.C. + walls). Above 1.5 D.L., a pattern of live load can make a span hog — check the spans for negative moments.",ar:"الحمل الحي ≤ 2 × الحمل الميت (الميت = ts γc + التشطيبات + الحوائط). ولو فوق 1.5 مرة الحمل الميت، ترتيب الحمل الحي ممكن يعمل عزم سالب في البحر — راجع البحور."}]},{t:"eq",tex:["M_o = \\dfrac{w_s\\,L_2\\,(L_1 - 2D/3)^2}{8},\\qquad M_o' = \\dfrac{w_s\\,L_1\\,(L_2 - 2D/3)^2}{8}"],caption:{en:"D = column (or head) size in the span direction: the reaction under the column is taken as a triangle whose resultant lies D/3 inside each face, so the span shortens by 2D/3. The second form for the other direction.",ar:"D = مقاس العمود (أو التاج) في اتجاه البحر: رد الفعل تحت العمود بيتاخد مثلث محصلته على بعد D/3 جوه كل وش، فالبحر بيقصر 2D/3. والصيغة التانية للاتجاه التاني."}},{t:"p",text:{en:"About 60 % of $M_o$ hogs over the supports and 40 % sags in the span; the column strip takes 75 % of the hogging and 62.5 % of the sagging moment (column and field strips equally wide, $L_2/2$ each):",ar:"حوالي 60 % من $M_o$ عزم سالب فوق الركائز و 40 % موجب في البحر؛ وشريحة العمود بتاخد 75 % من السالب و 62.5 % من الموجب (شريحة العمود والوسطى بنفس العرض، $L_2/2$ لكل واحدة):"}},{t:"table",head:[{en:"× M_o",ar:"× M_o"},{en:"exterior support −",ar:"ركيزة خارجية −"},{en:"end span +",ar:"بحر طرفي +"},{en:"1st interior support −",ar:"أول ركيزة وسطية −"},{en:"interior span +",ar:"بحر داخلي +"},{en:"interior support −",ar:"ركيزة وسطية −"}],rows:[[{en:"column strip",ar:"شريحة العمود"},"0.25","0.30","0.50","0.25","0.45"],[{en:"field strip",ar:"الشريحة الوسطى"},"0.05","0.20","0.20","0.15","0.15"],[{en:"column strip, marginal beam",ar:"شريحة العمود، بكمرة طرفية"},"0.20","0.30","0.50","0.25","0.45"],[{en:"field strip, marginal beam",ar:"الشريحة الوسطى، بكمرة طرفية"},"0.10","0.20","0.20","0.15","0.15"]],caption:{en:"The 0.50 against 0.45 at the first interior support is the part that goes into the column.",ar:"الـ 0.50 قصاد 0.45 عند أول ركيزة وسطية هو الجزء اللي بيروح للعمود."}},{t:"eq",tex:["MF = \\dfrac{b_{FS}}{B/2},\\qquad M_{FS,mod} = MF\\,M_{FS},\\qquad M_{CS,mod} = M_{CS} + M_{FS} - M_{FS,mod}"],caption:{en:"Modification factor (معامل التعديل) when the field strip is not half the width B: the field strip is scaled and the column strip takes the difference — the total stays the same.",ar:"معامل التعديل لما الشريحة الوسطى مش نص العرض B: الشريحة الوسطى بتتضرب فيه وشريحة العمود بتاخد الفرق — والمجموع ثابت."}},{t:"steps",items:[{en:"**Panels of different widths:** a set of strips is taken from mid-panel to mid-panel on the two sides of its column line, and $M_o$ uses that width.",ar:"**بواكي بعروض مختلفة:** مجموعة الشرائح بتتاخد من نص الباكية لنص الباكية على جنبين خط الأعمدة بتاعها، و $M_o$ بيتحسب بالعرض ده."},{en:"**A cantilever along an edge** (a balcony that continues the slab): the edge column strip becomes $L_2/4 + L_c$ wide — the cantilever band belongs to it — and the strip set reaches the tip; since the field strip is then narrower than half the set, MF < 1 moves moment into the column strip.",ar:"**كابولي على الحرف** (بلكونة مكمّلة البلاطة): شريحة العمود الطرفية بيبقى عرضها $L_2/4 + L_c$ — شريط الكابولي تبعها — ومجموعة الشرائح بتوصل لطرفه؛ وبما إن الشريحة الوسطى بقت أضيق من نص المجموعة، MF < 1 بينقل عزم لشريحة العمود."}]},{t:"p",text:{en:"**Example — the office floor** (all conditions hold: 4 × 3 bays, $6.4/5.6 = 1.14$, equal spans, $3.0 \\le 2\\times8.0$). $M_o = 16.0\\times5.6\\times(6.4 - 2\\times0.4/3)^2/8 = 421.3$ kN·m along x and $16.0\\times6.4\\times(5.6 - 0.267)^2/8 = 364.1$ kN·m along y. Along x the strips are equal (MF = 1): end bay column strip 105.3 / 126.4 / 210.7 and field strip 21.1 / 84.3 / 84.3 kN·m; interior bay 210.7 / 105.3 / 189.6 and 84.3 / 63.2 / 63.2 kN·m. Along y the field strip is 3.6 m: $MF = 3.6/3.2 = 1.125$, so the end bay becomes field strip 20.5 / 81.9 / 81.9 and column strip 88.7 / 100.1 / 172.9 kN·m.",ar:"**مثال — دور المكاتب** (كل الشروط متحققة: 4 × 3 بواكي، و $6.4/5.6 = 1.14$، وبحور متساوية، و $3.0 \\le 2\\times8.0$). $M_o = 16.0\\times5.6\\times(6.4 - 2\\times0.4/3)^2/8 = 421.3$ kN·m على x، و $16.0\\times6.4\\times(5.6 - 0.267)^2/8 = 364.1$ kN·m على y. على x الشرائح متساوية (MF = 1): الباكية الطرفية شريحة العمود 105.3 / 126.4 / 210.7 والوسطى 21.1 / 84.3 / 84.3 kN·m؛ والباكية الداخلية 210.7 / 105.3 / 189.6 و 84.3 / 63.2 / 63.2 kN·m. وعلى y الشريحة الوسطى 3.6 م: $MF = 3.6/3.2 = 1.125$، فالباكية الطرفية بتبقى الوسطى 20.5 / 81.9 / 81.9 وشريحة العمود 88.7 / 100.1 / 172.9 kN·m."}},{t:"p",text:{en:"**Heavy live load** ($L.L. > 1.5\\,D.L.$, still ≤ 2 D.L.). With the live load on alternate panels an unloaded span can hog. The code gives that negative moment directly — its bracket turns negative exactly when $L.L. > 1.5\\,D.L.$ — and the design then follows a “max-max” envelope: every section of the panel takes its worst value, and the top bars run on along the spans, lapped at mid-span over 60Ø.",ar:"**حمل حي تقيل** ($L.L. > 1.5\\,D.L.$، ولسه ≤ 2 D.L.). لما الحمل الحي يتحط على باكية وباكية، البحر اللي مش محمّل ممكن عزمه يبقى سالب. الكود بيدي العزم السالب ده على طول — والقوس بتاعه بيبقى سالب بالظبط لما $L.L. > 1.5\\,D.L.$ — والتصميم بيمشي على غلاف «أقصى-أقصى»: كل قطاع في الباكية بياخد أسوأ قيمة ليه، والحديد العلوي بيكمّل على طول البحور، ووصلته بالتراكب في نص البحر بطول 60Ø."}},{t:"eq",tex:["M_{CS}^{-} = \\left(D.L. - \\tfrac{2}{3}\\,L.L.\\right)\\dfrac{L_2}{40}\\left(L_1 - \\tfrac{2D}{3}\\right)^2,\\qquad M_{FS}^{-} = \\left(D.L. - \\tfrac{2}{3}\\,L.L.\\right)\\dfrac{L_2}{100}\\left(L_1 - \\tfrac{2D}{3}\\right)^2"],caption:{en:"Hogging moments in the spans of the column strip and of the field strip (kN·m on the strip). The envelope for the whole panel width: 0.30 M_o at the exterior support, 0.50 M_o in the end span, 0.60 M_o at the interior supports and 0.40 M_o in the interior spans — the column-strip and field-strip coefficients added together.",ar:"العزوم السالبة في بحور شريحة العمود والشريحة الوسطى (kN·m على الشريحة). والغلاف لعرض الباكية كله: 0.30 M_o عند الركيزة الخارجية، و 0.50 M_o في البحر الطرفي، و 0.60 M_o عند الركائز الوسطية، و 0.40 M_o في البحور الوسطية — يعني معاملات شريحة العمود والشريحة الوسطى مجموعين."}},{t:"lab",lab:"flatslab",height:480,props:{preset:"drops",missions:s,defaultTab:"steps"},caption:{en:"The office floor with drop panels and the solution open: follow M_o, the strips and the modification factor; then play with the spans.",ar:"دور المكاتب بالسقوط والحل مفتوح: تابع M_o والشرائح ومعامل التعديل؛ وبعدين العب بالبحور."}},{t:"quiz",q:{kind:"num",q:{en:"Panel 7.0 × 5.0 m, no drop panels. MF of the strips spanning the 5.0 m direction?",ar:"باكية 7.0 × 5.0 م من غير سقوط. قيمة MF للشرائح اللي بتشيل في اتجاه الـ 5.0 م؟"},answer:1.286,tol:.002,explain:{en:"$b_{CS} = 2.5$, $b_{FS} = 7.0 - 2.5 = 4.5$: $MF = 4.5/3.5 = 1.286$.",ar:"$b_{CS} = 2.5$، و $b_{FS} = 7.0 - 2.5 = 4.5$: $MF = 4.5/3.5 = 1.286$."}}}]},{id:"design",title:{en:"Designing the strips and drawing the plan",ar:"تصميم الشرائح ورسم اللوحة"},blocks:[{t:"eq",tex:["d = C_1\\sqrt{\\dfrac{M}{f_{cu}\\,b}} \\;\\Rightarrow\\; J,\\qquad A_s = \\dfrac{M}{J\\,f_y\\,d},\\qquad A_{s,min} = \\max\\left(\\dfrac{0.6}{f_y},\\ 0.0015\\right)b\\,d"],caption:{en:"b = the width of the strip (mm); dividing by b gives the steel per metre. 0.25 % instead of 0.15 % for mild steel.",ar:"b = عرض الشريحة (مم)؛ والقسمة على b بتدي الحديد لكل متر. و 0.25 % بدل 0.15 % للحديد الطري."}},{t:"steps",items:[{en:"The practical minimum in flat slabs is **5Ø12/m** (5Ø10/m in solid slabs); not more than 8 bars per metre, bars up to $t_s/10$.",ar:"أقل حديد عملي في البلاطات اللاكمرية **5Ø12 في المتر** (5Ø10 في المصمتة)؛ ومش أكتر من 8 أسياخ في المتر، والقطر لحد $t_s/10$."},{en:"If $t_s > 160$ mm add a top mesh 5Ø10/m wherever there is no top steel (shrinkage).",ar:"لو $t_s > 160$ مم ضيف شبكة علوية 5Ø10 في المتر في أي مكان مفيهوش حديد علوي (الانكماش)."},{en:"The edge column strip ($L_2/4$ wide) gets the same steel per metre as the main column strip.",ar:"شريحة العمود الطرفية (عرضها $L_2/4$) بتاخد نفس حديد المتر اللي في شريحة العمود الأساسية."},{en:"Design table: Strip | Section | M | b | d | C1 | J | As per strip | As per metre | bars per metre. The long direction is the lower layer «فرش» ($d = t_s - 30$), the short direction the «غطاء» ($d = t_s - 40$).",ar:"جدول التصميم: الشريحة | القطاع | M | b | d | C1 | J | As للشريحة | As للمتر | الأسياخ في المتر. الاتجاه الطويل هو الفرش ($d = t_s - 30$) والقصير الغطاء ($d = t_s - 40$)."},{en:"Plan: shade the column and field strips, draw one bar of each strip labelled $n\\,\\phi\\,d$/m — bottom bars in each panel, top bars over the column lines and across the field strips at the supports; offices often draw top and bottom steel on separate plans.",ar:"اللوحة: ظلّل شرائح الأعمدة والشرائح الوسطى، وارسم سيخ واحد من كل شريحة مكتوب عليه $n\\,\\phi\\,d$ في المتر — الحديد السفلي في كل باكية، والعلوي فوق خطوط الأعمدة وعلى الشرائح الوسطى عند الركائز؛ والمكاتب غالباً بترسم الحديد العلوي والسفلي في لوحتين."}]},{t:"p",text:{en:"**Example — the office floor along x** ($d = 170$ mm). First interior support, column strip: 210.7 kN·m on 2.8 m = 75.24 kN·m/m; $C_1 = 170/\\sqrt{75.24\\times10^6/(30\\times1000)} = 3.39$ → $J = 0.775$, $A_s = 75.24\\times10^6/(0.775\\times400\\times170) = 1428$ mm²/m → **8Ø16/m** (Ø12 would need 13 bars). End span 45.14 kN·m/m → 814 → 8Ø12/m; exterior support 37.62 → 671 → 6Ø12/m; field strips 30.09 → 536 → 5Ø12/m, and 7.52 → the minimum 5Ø12/m. Along y ($d = 160$): column strip at the first interior support $172.9/2.8 = 61.77$ kN·m/m → 1233 → 7Ø16/m. Since $t_s = 200 > 160$ mm, a top mesh 5Ø10/m covers the middle of the panels.",ar:"**مثال — دور المكاتب على x** ($d = 170$ مم). أول ركيزة وسطية، شريحة العمود: 210.7 kN·m على 2.8 م = 75.24 kN·m/m؛ و $C_1 = 170/\\sqrt{75.24\\times10^6/(30\\times1000)} = 3.39$ ← $J = 0.775$، و $A_s = 75.24\\times10^6/(0.775\\times400\\times170) = 1428$ mm²/m ← **8Ø16 في المتر** (Ø12 كان محتاج 13 سيخ). البحر الطرفي 45.14 kN·m/m ← 814 ← 8Ø12 في المتر؛ والركيزة الخارجية 37.62 ← 671 ← 6Ø12؛ والشرائح الوسطى 30.09 ← 536 ← 5Ø12، و 7.52 ← الحد الأدنى 5Ø12. وعلى y ($d = 160$): شريحة العمود عند أول ركيزة وسطية $172.9/2.8 = 61.77$ kN·m/m ← 1233 ← 7Ø16 في المتر. وبما إن $t_s = 200 > 160$ مم، شبكة علوية 5Ø10 في المتر بتغطي نص البواكي."}},{t:"p",text:{en:"**With drop panels** the column strip is X wide and the field strip $L - X$ (with the modification factor whenever $X \\ne L/2$), and the depth changes along the strip: the column-strip supports over the drop panel use $d = t_s + t_d - 30$ (long direction) or $t_s + t_d - 40$ (short); the spans and the field strips keep $t_s - 30$ / $t_s - 40$. **The cantilever floor of section 7, long direction** ($M_o = 18.275\\times6.0\\times(7.0 - 0.233)^2/8 = 627.6$ kN·m, CS = FS = 3.0 m): first interior support $0.50\\,M_o = 313.8$ kN·m → 104.6 kN·m/m with $d = 270$: $C_1 = 4.57$, $J = 0.820$, $A_s = 1181$ mm²/m → 6Ø16/m; end span $0.30\\,M_o = 188.3$ → 62.8 kN·m/m with $d = 170$ → 1165 mm²/m → 6Ø16/m; field strip $0.20\\,M_o = 125.5$ → 41.8 kN·m/m → 751 mm²/m → 7Ø12/m. Short direction over the drop ($d = 260$): the modified column strip, 245.0 kN·m on 3.0 m (section 12), → 951 mm²/m → 5Ø16/m.",ar:"**مع السقوط** شريحة العمود عرضها X والوسطى $L - X$ (بمعامل التعديل لما $X \\ne L/2$)، والعمق بيتغير على طول الشريحة: ركائز شريحة العمود فوق السقوط بتاخد $d = t_s + t_d - 30$ (الاتجاه الطويل) أو $t_s + t_d - 40$ (القصير)؛ والبحور والشرائح الوسطى بيفضلوا $t_s - 30$ / $t_s - 40$. **دور الكابولي بتاع الجزء 7، الاتجاه الطويل** ($M_o = 18.275\\times6.0\\times(7.0 - 0.233)^2/8 = 627.6$ kN·m، وشريحة العمود = الوسطى = 3.0 م): أول ركيزة وسطية $0.50\\,M_o = 313.8$ kN·m ← 104.6 kN·m/m بـ $d = 270$: $C_1 = 4.57$ و $J = 0.820$ و $A_s = 1181$ مم²/م ← 6Ø16 في المتر؛ والبحر الطرفي $0.30\\,M_o = 188.3$ ← 62.8 kN·m/m بـ $d = 170$ ← 1165 مم²/م ← 6Ø16 في المتر؛ والشريحة الوسطى $0.20\\,M_o = 125.5$ ← 41.8 kN·m/m ← 751 مم²/م ← 7Ø12 في المتر. والاتجاه القصير فوق السقوط ($d = 260$): شريحة العمود المعدّلة، 245.0 kN·m على 3.0 م (الجزء 12)، ← 951 مم²/م ← 5Ø16 في المتر."}},{t:"note",tone:"info",text:{en:"The edge column strip gets the same steel per metre as the main column strip **only without a marginal beam**; next to a marginal beam it gets half of it — the beam takes the edge moment. A slab symmetric in both directions is designed as one strip and the same steel is placed both ways, with the larger cover ($d = t_s - 40$).",ar:"شريحة العمود الطرفية بتاخد نفس حديد المتر بتاع شريحة العمود الأساسية **بس لو مفيش كمرة طرفية**؛ جنب الكمرة الطرفية بتاخد نصه — الكمرة بتشيل عزم الحرف. والبلاطة المتماثلة في الاتجاهين بتتصمم كشريحة واحدة ونفس الحديد بيتحط في الاتجاهين، بالغطاء الأكبر ($d = t_s - 40$)."}},{t:"quiz",q:{kind:"mcq",q:{en:"A column strip needs As = 1100 mm²/m and the slab allows up to Ø20. Which bars (at most 8 per metre)?",ar:"شريحة عمود محتاجة As = 1100 mm²/m والبلاطة بتسمح لحد Ø20. أنهي أسياخ (بحد أقصى 8 في المتر)؟"},options:[{en:"10Ø12/m",ar:"10Ø12 في المتر"},{en:"6Ø16/m",ar:"6Ø16 في المتر"},{en:"4Ø20/m",ar:"4Ø20 في المتر"}],answer:1,explain:{en:"Ø12 would need 10 bars (> 8); Ø16: $1100/201 = 5.5$ → 6Ø16 = 1206 mm²/m; four bars are below the minimum of five.",ar:"Ø12 كان محتاج 10 أسياخ (> 8)؛ و Ø16: $1100/201 = 5.5$ ← 6Ø16 = 1206 mm²/m؛ وأربع أسياخ أقل من الحد الأدنى خمسة."}}}]},{id:"transfer",title:{en:"Moments into the columns and the extra steel over them",ar:"العزوم اللي بتروح للأعمدة والحديد الإضافي فوقها"},blocks:[{t:"p",text:{en:"A slab that hogs differently on the two sides of a column twists it: the difference goes into the column. With the empirical method: an **interior column** takes $M_c = 0.5$ of the column-strip moment at that support; an **edge column** $0.9$ of the exterior column-strip moment ($0.9\\times0.25\\,M_o$); a **corner column** $0.9\\times0.25\\,M_o\\times0.5$ in each direction (its edge strip is half as wide). A part $\\gamma_f$ of $M_c$ passes by bending of a narrow band of slab over the column; the rest by eccentric shear — that is why punching has its β.",ar:"البلاطة اللي عزمها السالب مختلف على الناحيتين بتلوي العمود: والفرق بيروح للعمود. بالطريقة التقريبية: **العمود الداخلي** بياخد $M_c = 0.5$ من عزم شريحة العمود عند الركيزة دي؛ و**العمود الطرفي** $0.9$ من عزم شريحة العمود الخارجي ($0.9\\times0.25\\,M_o$)؛ و**العمود الركني** $0.9\\times0.25\\,M_o\\times0.5$ في كل اتجاه (شريحته الطرفية نص العرض). جزء $\\gamma_f$ من $M_c$ بيعدّي بانحناء شريط ضيق من البلاطة فوق العمود؛ والباقي بقص لامركزي — وعشان كده القص الثاقب فيه β."}},{t:"eq",tex:["\\gamma_f = \\dfrac{1}{1 + \\frac{2}{3}\\sqrt{b_1/b_2}},\\qquad M_f = \\gamma_f\\,M_c,\\qquad b_e = \\min(c_2 + 3\\,t_s,\\ c_2 + c_1)","\\Delta M = \\dfrac{M_f}{b_e} - \\dfrac{M_{CS}}{b_{CS}}"],caption:{en:"b1 = c1 + d along the moment, b2 = c2 + d across it. Edge and corner columns use the one-sided width min(c2 + 1.5 ts, c2 + c1/2). If ΔM > 0, design extra top bars for ΔM per metre and place them within b_e.",ar:"b1 = c1 + d في اتجاه العزم، و b2 = c2 + d عمودي عليه. الأعمدة الطرفية والركنية بتستخدم العرض من ناحية واحدة min(c2 + 1.5 ts, c2 + c1/2). ولو ΔM > 0 صمم حديد علوي إضافي لـ ΔM في المتر وحطه جوه b_e."}},{t:"p",text:{en:"**Example — the office floor, along x.** Interior column at the first interior support: the column strip carries 210.7 kN·m on that column line, so $M_c = 0.5\\times210.7 = 105.3$ kN·m; $b_1 = b_2 = 570$ mm → $\\gamma_f = 0.60$ and $M_f = 63.2$ kN·m; $b_e = \\min(0.4 + 0.6,\\ 0.4 + 0.4) = 0.8$ m → $63.2/0.8 = 79.0$ against $210.7/2.8 = 75.2$ kN·m/m → $\\Delta M = 3.76$ kN·m/m → **2Ø12** extra over the column. Edge column on axis 1: $M_{CS} = 105.3$, $M_c = 0.9\\times105.3 = 94.8$, $M_f = 56.9$ kN·m, $b_e = \\min(0.4 + 0.3,\\ 0.4 + 0.2) = 0.6$ m → 94.8 against 37.6 → $\\Delta M = 57.2$ kN·m/m → **6Ø12** within 0.6 m: the exterior columns need the most extra steel. A 300 × 500 column bent about its 300 mm side with $d = 130$: $b_1 = 430$, $b_2 = 630$ → $\\gamma_f = 0.645$. **A column next to a cantilever** gets $M_c = 0.9\\,(0.25\\,M_o - M_{cant})$: the cantilever balances part of the exterior moment — with $0.25\\,M_o = 90$ and a cantilever moment of 40 kN·m on the same strip width, $M_c = 0.9\\times(90 - 40) = 45$ kN·m instead of $0.9\\times90 = 81$ kN·m.",ar:"**مثال — دور المكاتب على x.** عمود داخلي عند أول ركيزة وسطية: شريحة العمود شايلة 210.7 kN·m على خط الأعمدة ده، يبقى $M_c = 0.5\\times210.7 = 105.3$ kN·m؛ و $b_1 = b_2 = 570$ مم ← $\\gamma_f = 0.60$ و $M_f = 63.2$ kN·m؛ و $b_e = \\min(0.4 + 0.6,\\ 0.4 + 0.4) = 0.8$ م ← $63.2/0.8 = 79.0$ قصاد $210.7/2.8 = 75.2$ kN·m/m ← $\\Delta M = 3.76$ kN·m/m ← **2Ø12** زيادة فوق العمود. العمود الطرفي على المحور 1: $M_{CS} = 105.3$، و $M_c = 0.9\\times105.3 = 94.8$، و $M_f = 56.9$ kN·m، و $b_e = \\min(0.4 + 0.3,\\ 0.4 + 0.2) = 0.6$ م ← 94.8 قصاد 37.6 ← $\\Delta M = 57.2$ kN·m/m ← **6Ø12** جوه 0.6 م: الأعمدة الخارجية هي اللي محتاجة أكتر حديد إضافي. وعمود 300 × 500 منحني حوالين ضلعه 300 مم و $d = 130$: $b_1 = 430$ و $b_2 = 630$ ← $\\gamma_f = 0.645$. **العمود اللي جنب كابولي** بياخد $M_c = 0.9\\,(0.25\\,M_o - M_{cant})$: الكابولي بيوازن جزء من العزم الخارجي — لو $0.25\\,M_o = 90$ وعزم الكابولي 40 kN·m على نفس عرض الشريحة، يبقى $M_c = 0.9\\times(90 - 40) = 45$ kN·m بدل $0.9\\times90 = 81$ kN·m."}},{t:"p",text:{en:"**Edge and corner columns, more exactly.** At an edge column bending across the free edge the critical section is cut by the edge: its side along the moment is only $b_1 = c_1 + d/2$, while $b_2 = c_2 + d$; the band that carries $M_f$ runs along the edge with slab on both sides of the column, so it keeps the full width. At a corner column both sides are cut and the band is one-sided:",ar:"**الأعمدة الطرفية والركنية بدقة أكتر.** في العمود الطرفي اللي بينحني عمودي على الحرف الحر، القطاع الحرج مقطوع عند الحرف: ضلعه في اتجاه العزم بيبقى $b_1 = c_1 + d/2$ بس، و $b_2 = c_2 + d$؛ والشريط اللي بيشيل $M_f$ ماشي مع الحرف والبلاطة موجودة على الناحيتين من العمود، فبياخد العرض الكامل. وفي العمود الركني الضلعين مقطوعين والشريط من ناحية واحدة:"}},{t:"eq",tex:["b_{1,edge} = c_1 + \\tfrac{d}{2},\\qquad b_{2,edge} = c_2 + d,\\qquad b_{e,edge} = \\min(c_2 + 3\\,t_s,\\ c_1 + c_2)","b_{1,corner} = c_1 + \\tfrac{d}{2},\\qquad b_{2,corner} = c_2 + \\tfrac{d}{2},\\qquad b_{e,corner} = \\min\\left(c_2 + 1.5\\,t_s,\\ c_2 + \\tfrac{c_1}{2}\\right)"],caption:{en:"b1 along the moment, b2 across it; the edge-column line is for bending perpendicular to the free edge.",ar:"b1 في اتجاه العزم و b2 عمودي عليه؛ وسطر العمود الطرفي للانحناء العمودي على الحرف الحر."}},{t:"p",text:{en:"**For the office floor** the edge column on axis 1 would get $b_1 = 485$, $b_2 = 570$ mm → $\\gamma_f = 0.619$, $M_f = 58.7$ kN·m and $b_e = \\min(0.4 + 0.6,\\ 0.8) = 0.8$ m → $73.4 - 37.6 = 35.8$ kN·m/m → 5Ø12 within 0.8 m instead of 6Ø12 within 0.6 m: the one-sided band used above (and in the lab) is the simpler, safer choice. **Example — a 7.0 × 6.0 m floor on 600 × 600 columns** ($w_s = 18.3$, $M_o = 597.9$ kN·m, $t_s = 220$, $d = 190$, fcu 25, fy 350). The interior column needs nothing extra: $89.68/1.20 = 74.7 < 298.9/3.0 = 99.6$ kN·m/m. The edge column: $M_c = 0.9\\times0.25\\times597.9 = 134.5$ kN·m; $b_1 = 695$, $b_2 = 790$ → $\\gamma_f = 0.615$, $M_f = 82.77$ kN·m; $b_e = \\min(0.6 + 0.66,\\ 1.2) = 1.2$ m → $82.77/1.2 = 68.97 > 149.47/3.0 = 49.82$ → $\\Delta M = 19.15$ kN·m/m: $C_1 = 6.87$, $A_s = 349$ mm²/m × 1.2 = 418 mm² → **4Ø12** within 1.2 m.",ar:"**في دور المكاتب** العمود الطرفي على المحور 1 كان هياخد $b_1 = 485$ و $b_2 = 570$ مم ← $\\gamma_f = 0.619$ و $M_f = 58.7$ kN·m و $b_e = \\min(0.4 + 0.6,\\ 0.8) = 0.8$ م ← $73.4 - 37.6 = 35.8$ kN·m/m ← 5Ø12 جوه 0.8 م بدل 6Ø12 جوه 0.6 م: الشريط اللي من ناحية واحدة اللي استخدمناه فوق (وفي المعمل) هو الاختيار الأبسط والأأمن. **مثال — دور 7.0 × 6.0 م على أعمدة 600 × 600** ($w_s = 18.3$، و $M_o = 597.9$ kN·m، و $t_s = 220$، و $d = 190$، و fcu 25، و fy 350). العمود الداخلي مش محتاج حاجة زيادة: $89.68/1.20 = 74.7 < 298.9/3.0 = 99.6$ kN·m/m. العمود الطرفي: $M_c = 0.9\\times0.25\\times597.9 = 134.5$ kN·m؛ و $b_1 = 695$ و $b_2 = 790$ ← $\\gamma_f = 0.615$ و $M_f = 82.77$ kN·m؛ و $b_e = \\min(0.6 + 0.66,\\ 1.2) = 1.2$ م ← $82.77/1.2 = 68.97 > 149.47/3.0 = 49.82$ ← $\\Delta M = 19.15$ kN·m/m: $C_1 = 6.87$، و $A_s = 349$ مم²/م × 1.2 = 418 مم² ← **4Ø12** جوه 1.2 م."}},{t:"p",text:{en:"**Loads for the columns.** A flat-slab column is designed for the worst pair of N and M from a few loading patterns: full load on every panel gives the largest N, while panels carrying only $g_s = 0.9\\,D.L.$ (0.9 of the slab, floor cover and walls) give the largest unbalanced moment. The factor 1.1 adds the column’s own weight, and N and M must always come from the same pattern:",ar:"**أحمال الأعمدة.** عمود البلاطة اللاكمرية بيتصمم لأسوأ زوج N و M من كام حالة تحميل: الحمل الكامل على كل البواكي بيدي أكبر N، والبواكي اللي شايلة $g_s = 0.9\\,D.L.$ بس (0.9 من وزن البلاطة والتشطيبات والحوائط) بتدي أكبر عزم غير متوازن. المعامل 1.1 بيضيف وزن العمود نفسه، و N و M لازم ييجوا دايماً من نفس حالة التحميل:"}},{t:"table",head:[{en:"Column",ar:"العمود"},{en:"loading",ar:"التحميل"},{en:"P per floor",ar:"P لكل دور"},"$M_c$"],rows:[[{en:"interior",ar:"داخلي"},{en:"all panels loaded (largest N)",ar:"كل البواكي محمّلة (أكبر N)"},"$1.1\\,w_s L_1 L_2$","0"],[{en:"interior",ar:"داخلي"},{en:"one side $w_s$, the other $g_s$",ar:"ناحية $w_s$ والتانية $g_s$"},"$1.1\\,(w_s + g_s)\\tfrac{L_1}{2}L_2$","$0.5\\times0.50\\,M_o$"],[{en:"edge",ar:"طرفي"},{en:"panel loaded",ar:"الباكية محمّلة"},"$1.1\\,w_s\\tfrac{L_1}{2}L_2$",{en:"$0.9\\times0.25\\,M_o$ (0.20 with a marginal beam)",ar:"$0.9\\times0.25\\,M_o$ (0.20 مع كمرة طرفية)"}],[{en:"at a cantilever",ar:"عند كابولي"},{en:"cantilever loaded",ar:"الكابولي محمّل"},"$1.1\\,w_s(\\tfrac{L_1}{2} + L_c)L_2$","$0.9\\,(0.25\\,M_o - w_s\\tfrac{L_c^2}{2}b_{CS})$"],[{en:"at a cantilever",ar:"عند كابولي"},{en:"cantilever with $g_s$ only",ar:"الكابولي عليه $g_s$ بس"},"$1.1\\,(w_s\\tfrac{L_1}{2}L_2 + g_s L_c L_2)$","$0.9\\,(0.25\\,M_o - g_s\\tfrac{L_c^2}{2}b_{CS})$"],[{en:"corner",ar:"ركني"},{en:"panel loaded",ar:"الباكية محمّلة"},"$1.1\\,w_s\\tfrac{L_1}{2}\\tfrac{L_2}{2}$",{en:"$0.5\\times0.9\\times0.25\\,M_o$ each way (biaxial)",ar:"$0.5\\times0.9\\times0.25\\,M_o$ في كل اتجاه (في الاتجاهين)"}]],caption:{en:"L1 in the direction of the moment, L2 across it; P is summed over the floors above. Use the fully loaded case for the ground-floor column (largest N) and the partly loaded cases for the last-floor column, which carries one floor but the full moment.",ar:"L1 في اتجاه العزم و L2 عمودي عليه؛ و P بتتجمع على كل الأدوار اللي فوق. استخدم حالة الحمل الكامل لعمود الدور الأرضي (أكبر N) والحالات المحمّلة جزئياً لعمود الدور الأخير، اللي شايل دور واحد بس لكن بالعزم كله."}},{t:"eq",tex:["M_{c,below} = \\dfrac{I_1/h_1}{\\sum I/h}\\,M_c,\\qquad M_{c,above} = \\dfrac{I_2/h_2}{\\sum I/h}\\,M_c"],caption:{en:"At a typical floor the unbalanced moment splits between the column below and the column above by stiffness; the last-floor column takes all of it. With the frame method M_c is simply the column end moment of the frame.",ar:"في الدور المتكرر العزم غير المتوازن بيتقسم بين العمود اللي تحت واللي فوق بنسبة الجساءة؛ وعمود الدور الأخير بياخده كله. وفي طريقة الإطار M_c هو ببساطة عزم طرف العمود في الإطار."}},{t:"p",text:{en:"**The office floor.** An interior column at the first interior support: all loaded, $P = 1.1\\times16.0\\times6.4\\times5.6 = 630.8$ kN per floor with no moment; one side with $g_s = 0.9\\times8.0 = 7.2$ only: $P = 1.1\\times(16.0 + 7.2)\\times3.2\\times5.6 = 457.3$ kN with $M_c = 105.3$ kN·m — split 52.7 + 52.7 between two equal columns at a typical floor, all 105.3 into the column under the roof. Edge column: $1.1\\times16.0\\times3.2\\times5.6 = 315.4$ kN with 94.8 kN·m; corner column: 157.7 kN with $0.5\\times0.9\\times105.3 = 47.4$ and $0.5\\times0.9\\times91.0 = 41.0$ kN·m. **The cantilever floor** (short direction, $M_o = 512.8$ kN·m, $b_{CS} = 3.0$ m, $L_c = 2.0$ m): cantilever loaded, $M_c = 0.9\\times(128.2 - 18.275\\times2.0\\times3.0) = 16.7$ kN·m with $P = 678.5$ kN; cantilever carrying only $g_s = 0.9\\times9.625 = 8.66$, $M_c = 0.9\\times(128.2 - 8.66\\times2.0\\times3.0) = 68.6$ kN·m with $P = 535.7$ kN — the unloaded cantilever gives the design moment.",ar:"**دور المكاتب.** عمود داخلي عند أول ركيزة وسطية: كله محمّل، $P = 1.1\\times16.0\\times6.4\\times5.6 = 630.8$ kN لكل دور من غير عزم؛ وناحية عليها $g_s = 0.9\\times8.0 = 7.2$ بس: $P = 1.1\\times(16.0 + 7.2)\\times3.2\\times5.6 = 457.3$ kN مع $M_c = 105.3$ kN·m — بيتقسم 52.7 + 52.7 بين عمودين متساويين في الدور المتكرر، والـ 105.3 كلها بتروح للعمود اللي تحت السطح. العمود الطرفي: $1.1\\times16.0\\times3.2\\times5.6 = 315.4$ kN مع 94.8 kN·m؛ والعمود الركني: 157.7 kN مع $0.5\\times0.9\\times105.3 = 47.4$ و $0.5\\times0.9\\times91.0 = 41.0$ kN·m. **دور الكابولي** (الاتجاه القصير، $M_o = 512.8$ kN·m، و $b_{CS} = 3.0$ م، و $L_c = 2.0$ م): الكابولي محمّل، $M_c = 0.9\\times(128.2 - 18.275\\times2.0\\times3.0) = 16.7$ kN·m مع $P = 678.5$ kN؛ والكابولي شايل $g_s = 0.9\\times9.625 = 8.66$ بس، $M_c = 0.9\\times(128.2 - 8.66\\times2.0\\times3.0) = 68.6$ kN·m مع $P = 535.7$ kN — الكابولي الفاضي هو اللي بيدي عزم التصميم."}},{t:"quiz",q:{kind:"num",q:{en:"Column 400 mm along the moment × 800 mm across it, d = 200 mm. γf?",ar:"عمود 400 مم في اتجاه العزم × 800 مم عمودي عليه، و d = 200 مم. قيمة γf؟"},answer:.659,tol:.005,explain:{en:"$b_1 = 600$, $b_2 = 1000$: $1/(1 + \\frac{2}{3}\\sqrt{0.6}) = 1/1.516 = 0.659$.",ar:"$b_1 = 600$ و $b_2 = 1000$: $1/(1 + \\frac{2}{3}\\sqrt{0.6}) = 1/1.516 = 0.659$."}}}]},{id:"frame",title:{en:"When the table does not apply: the frame-analysis method",ar:"لما الجدول مايطبّقش: طريقة تحليل الإطار"},blocks:[{t:"p",text:{en:"Fewer than three bays, unequal spans, long panels or heavy live loads put a floor outside the empirical method. Then the code uses the **frame-analysis method** (طريقة الإطار المكافئ): the floor is cut along the panel centre lines into one-storey plane frames in each direction — a frame of width L2 carries $w = w_s\\,L_2$ — with the columns above and below fixed at their far ends. Columns may be offset by up to 10 % of the span; beyond that, a computer model (e.g. SAP) is needed.",ar:"أقل من تلات بواكي، أو بحور مش متساوية، أو بواكي طويلة، أو أحمال حية تقيلة بيطلّعوا الدور برّه الطريقة التقريبية. ساعتها الكود بيستخدم **طريقة الإطار المكافئ**: الدور بيتقطع على محاور البواكي لإطارات مستوية من دور واحد في كل اتجاه — إطار عرضه L2 شايل $w = w_s\\,L_2$ — والأعمدة اللي فوق واللي تحت ثابتة من أطرافها البعيدة. الأعمدة ممكن تبقى مزاحة لحد 10 % من البحر؛ أكتر من كده محتاجين نموذج على الكمبيوتر (زي SAP)."}},{t:"eq",tex:["I_s = \\dfrac{I_1\\,(L_1 - X) + I_2\\,X}{L_1},\\qquad I_1 = \\dfrac{L\\,t_s^3}{12},\\qquad I_2 = \\dfrac{L\\,t_{av}^3}{12},\\qquad t_{av} = t_s + \\dfrac{t_d}{4}","I_c = \\psi\\,I,\\qquad \\psi_{edge} = 0.6,\\qquad \\psi_{int} = 0.3","\\psi_{edge} = \\left[0.6 + 0.4\\left(\\dfrac{\\alpha\\,L_{2a}}{L_{1a}}\\right)^2\\right]\\left(\\dfrac{L_{2a}}{L_{1a}}\\right)^2,\\qquad \\psi_{int} = \\left[0.3 + 0.7\\left(\\dfrac{\\alpha\\,L_{2a}}{L_{1a}}\\right)^2\\right]\\left(\\dfrac{L_{2a}}{L_{1a}}\\right)^2","K_s = \\dfrac{I_s}{L_1},\\qquad K_c = \\dfrac{I_c}{h},\\qquad D.F. = \\dfrac{K}{\\sum K},\\qquad FEM = \\dfrac{w\\,L_1^2}{12}"],caption:{en:"L = frame width; without drop panels I_s = I1. ψ = 0.6 / 0.3 are the simplified column factors used in the worked examples; the full expressions (third line) use α = I of the marginal beam / I of the slab and the average spans L1a, L2a — the square covers α as well. K_s = ½ I_s/L when symmetry is used; D.F. (distribution factor) = 0 for a cantilever or a fixed end; FEM = fixed-end moment.",ar:"L = عرض الإطار؛ ومن غير سقوط I_s = I1. و ψ = 0.6 / 0.3 معاملات الأعمدة المبسطة اللي كل الأمثلة بتستخدمها؛ والصيغ الكاملة (السطر التالت) بتستخدم α = عزم قصور الكمرة الطرفية / عزم قصور البلاطة ومتوسط البحور L1a و L2a — والتربيع بيشمل α كمان. و K_s = ½ I_s/L لو استخدمنا التماثل؛ ومعامل التوزيع D.F. = 0 للكابولي أو للطرف الثابت؛ و FEM هي عزوم التثبيت."}},{t:"table",head:[{en:"Frame moment",ar:"عزم الإطار"},{en:"exterior support",ar:"الركيزة الخارجية"},{en:"interior supports",ar:"الركائز الداخلية"},{en:"spans",ar:"البحور"}],rows:[[{en:"column strip",ar:"شريحة العمود"},"80 %","75 %","55 %"],[{en:"field strip",ar:"الشريحة الوسطى"},"20 %","25 %","45 %"]],caption:{en:"A cantilever moment of the frame is split between the strips by their widths: M(strip) = (b/L) M_c.",ar:"عزم الكابولي في الإطار بيتقسم على الشرائح بنسبة عرضها: M(الشريحة) = (b/L) M_c."}},{t:"p",text:{en:"**Example — the office floor with drop panels, a frame along x** (width 5.6 m): $I_1 = 5600\\times180^3/12 = 2.722\\times10^9$, $t_{av} = 180 + 90/4 = 202.5$ mm, $I_2 = 3.875\\times10^9$ and $I_s = (2.722\\times3.6 + 3.875\\times2.8)/6.4\\times10^9 = 3.226\\times10^9$ mm⁴. Interior column 400 × 400: $I_c = 0.3\\times400^4/12 = 0.64\\times10^9$ mm⁴. $K_s = 3.226\\times10^9/6400 = 5.04\\times10^5$, $K_c = 0.64\\times10^9/3600 = 1.78\\times10^5$ mm³; at an interior joint (two slabs, a column above and one below) D.F. = 0.370 for each slab and 0.130 for each column. $FEM = 15.99\\times5.6\\times6.4^2/12 = 305.6$ kN·m. After the moment distribution, 75 % of every interior support moment and 55 % of every span moment go to the column strip.",ar:"**مثال — دور المكاتب بالسقوط، إطار على x** (عرضه 5.6 م): $I_1 = 5600\\times180^3/12 = 2.722\\times10^9$، و $t_{av} = 180 + 90/4 = 202.5$ مم، و $I_2 = 3.875\\times10^9$، و $I_s = (2.722\\times3.6 + 3.875\\times2.8)/6.4\\times10^9 = 3.226\\times10^9$ مم⁴. العمود الداخلي 400 × 400: $I_c = 0.3\\times400^4/12 = 0.64\\times10^9$ مم⁴. و $K_s = 3.226\\times10^9/6400 = 5.04\\times10^5$، و $K_c = 0.64\\times10^9/3600 = 1.78\\times10^5$ مم³؛ وعند عقدة داخلية (بلاطتين وعمود فوق وعمود تحت) D.F. = 0.370 لكل بلاطة و 0.130 لكل عمود. و $FEM = 15.99\\times5.6\\times6.4^2/12 = 305.6$ kN·m. وبعد توزيع العزوم، 75 % من عزم كل ركيزة وسطية و 55 % من عزم كل بحر بيروحوا لشريحة العمود."}},{t:"p",text:{en:"**When and how.** A direction needs frames when it has fewer than three bays or adjacent spans differ by more than 10 %; the two directions may use different methods — empirical where the conditions hold, frames in the other. The column inertia before ψ is $b^4/12$ for a square, $b\\,t^3/12$ for a rectangle ($t$ = its side in the plane of the frame) and $\\pi D^4/64$ for a circle; a drop panel enters approximately through $t_{av}$.",ar:"**إمتى وإزاي.** الاتجاه محتاج إطارات لما يكون فيه أقل من تلات بواكي أو بحور متجاورة مختلفة أكتر من 10 %؛ وممكن كل اتجاه ياخد طريقة — التقريبية مكان ما الشروط متحققة، والإطارات في الاتجاه التاني. عزم قصور العمود قبل ψ: $b^4/12$ للمربع، و $b\\,t^3/12$ للمستطيل ($t$ = ضلعه اللي في مستوى الإطار)، و $\\pi D^4/64$ للدائري؛ والسقوط بيدخل تقريبياً عن طريق $t_{av}$."}},{t:"steps",items:[{en:"**Axis of symmetry through a span:** cut the frame there and give the half span $K = \\tfrac{1}{2}I/L$, with no carry-over to the cut end.",ar:"**محور التماثل بيعدّي في نص بحر:** اقطع الإطار هناك وادّي نص البحر $K = \\tfrac{1}{2}I/L$، ومفيش انتقال للطرف المقطوع."},{en:"**Axis through a column:** that joint does not rotate — treat it as fixed and keep $K = I/L$ for the spans beside it (not halved: their two end moments differ).",ar:"**المحور بيعدّي في عمود:** العقدة دي مابتلفّش — اعتبرها طرف ثابت وسيب $K = I/L$ للبحور اللي جنبها (من غير تنصيف: عزمي طرفيها مختلفين)."},{en:"**Single-storey frame (a roof):** no columns above and no wall load. The middle column gets moment only from unsymmetrical live-load patterns; if those are not analysed, give it half the moment of the exterior column.",ar:"**إطار دور واحد (سطح):** مفيش أعمدة فوق ولا حمل حوائط. العمود الأوسط مابياخدش عزم غير من ترتيبات الحمل الحي غير المتماثلة؛ ولو ماتحللتش، اديله نص عزم العمود الخارجي."},{en:"**Cantilevers:** the cantilever moment enters its joint as a known moment (D.F. = 0), is split between the strips by their widths and is never multiplied by the modification factor.",ar:"**الكوابيل:** عزم الكابولي بيدخل العقدة بتاعته كعزم معروف (D.F. = 0)، وبيتقسم على الشرائح بنسبة عرضها، وعمره ما بيتضرب في معامل التعديل."}]},{t:"p",text:{en:"**Strip widths, special cases.** A strip set runs from mid-panel to mid-panel with a column strip $L_2/4$ wide on each side of the column line, and the column strip is equally wide in both directions. A set that ends in a cantilever has $b_{CS} = L_2/4 + L_c$ — the whole cantilever belongs to the column strip. A short span that hogs over its whole length (a small bay between two big ones) belongs wholly to the column strip: $b_{CS} = L_2/4 + L_{small}/2$ — e.g. $6.0/4 + 2.5/2 = 2.75$ m of a 4.75 m set, so $MF = 2.0/(4.75/2) = 0.842$.",ar:"**عرض الشرائح، حالات خاصة.** مجموعة الشرائح بتمتد من نص الباكية لنص الباكية، وشريحة العمود عرضها $L_2/4$ من كل ناحية من خط الأعمدة، وبنفس العرض في الاتجاهين. المجموعة اللي بتخلص بكابولي فيها $b_{CS} = L_2/4 + L_c$ — الكابولي كله تبع شريحة العمود. والبحر القصير اللي عزمه سالب على طوله كله (باكية صغيرة بين باكيتين كبار) بيبقى كله تبع شريحة العمود: $b_{CS} = L_2/4 + L_{small}/2$ — مثلاً $6.0/4 + 2.5/2 = 2.75$ م من مجموعة 4.75 م، يبقى $MF = 2.0/(4.75/2) = 0.842$."}},{t:"p",text:{en:"**Example — two bays each way, 6.5 × 5.5 m** (ground + 4 floors, h = 4.0 m, fcu 25, fy 350, F.C. 1.5, walls 1.5, L.L. 2.0): two bays → frames in both directions. $t_s = 6500/32 = 203$ → 220 mm and $w_s = 15.1$ kN/m²; 350 mm columns punch ($q_{up} = 1.50 > 1.29$), 500 × 500 pass ($Q_{up} = 532.6$ kN, $q_{up} = 1.17$). **Long frames** (5.5 m wide, $w = 83.05$ kN/m): $I_c = 0.6\\times500^4/12 = 3.125\\times10^9$ mm⁴ at the edge columns, $I_s = 5500\\times220^3/12 = 4.88\\times10^9$ mm⁴, $K_s = 7.51\\times10^5$ and $K_c = 7.81\\times10^5$ mm³ → at the edge joint D.F. = 0.325 for the slab and 0.338 for each column. The frame is symmetric about the middle column, which is therefore fixed, and one balancing step finishes it: $FEM = 83.05\\times6.5^2/12 = 292.4$ → 197.5 kN·m at the edge, 339.9 at the middle, 169.9 at mid-span, and 98.8 kN·m into each edge column (49.4 at its far end). Column strips 158.0 / 254.9 / 93.5, field strips 39.5 / 85.0 / 76.5 kN·m; over the middle column $254.9/2.75 = 92.7$ kN·m/m → 8Ø18/m. **Short frames** (6.5 m wide, $w = 98.15$ kN/m): D.F. 0.402 / 0.299, $FEM = 247.4$ → 148.1 / 297.1 / 148.6 kN·m; $b_{FS} = 6.5 - 2.75 = 3.75$ m, $MF = 3.75/3.25 = 1.154$ → modified column strip 113.9 / 211.4 / 71.4 kN·m. **The edge column** gets $P = 1.1\\times15.1\\times3.25\\times5.5 = 296.9$ kN per floor, 1484.5 kN at the ground floor, with 98.8 kN·m from the frame; $\\lambda = 1.3\\times(4.0 - 0.22)/0.5 = 9.8 < 10$ — a short column whose minimum steel, $0.8\\%\\times500^2 = 2000$ mm² (12Ø16), governs.",ar:"**مثال — باكيتين في كل اتجاه، 6.5 × 5.5 م** (أرضي + 4 أدوار، و h = 4.0 م، و fcu 25، و fy 350، والتشطيبات 1.5، والحوائط 1.5، والحمل الحي 2.0): باكيتين ← إطارات في الاتجاهين. $t_s = 6500/32 = 203$ ← 220 مم و $w_s = 15.1$ kN/m²؛ الأعمدة 350 مم بتتخرم ($q_{up} = 1.50 > 1.29$)، والـ 500 × 500 بتعدّي ($Q_{up} = 532.6$ kN، و $q_{up} = 1.17$). **الإطارات الطويلة** (عرضها 5.5 م، و $w = 83.05$ kN/m): $I_c = 0.6\\times500^4/12 = 3.125\\times10^9$ مم⁴ للأعمدة الطرفية، و $I_s = 5500\\times220^3/12 = 4.88\\times10^9$ مم⁴، و $K_s = 7.51\\times10^5$ و $K_c = 7.81\\times10^5$ مم³ ← عند العقدة الطرفية D.F. = 0.325 للبلاطة و 0.338 لكل عمود. الإطار متماثل حوالين العمود الأوسط، فالعقدة دي ثابتة، وخطوة توزيع واحدة بتخلّصه: $FEM = 83.05\\times6.5^2/12 = 292.4$ ← 197.5 kN·m عند الطرف، و 339.9 في النص، و 169.9 في نص البحر، و 98.8 kN·m لكل عمود طرفي (و 49.4 عند طرفه البعيد). شرائح الأعمدة 158.0 / 254.9 / 93.5، والشرائح الوسطى 39.5 / 85.0 / 76.5 kN·m؛ وفوق العمود الأوسط $254.9/2.75 = 92.7$ kN·m/m ← 8Ø18 في المتر. **الإطارات القصيرة** (عرضها 6.5 م، و $w = 98.15$ kN/m): D.F. = 0.402 / 0.299، و $FEM = 247.4$ ← 148.1 / 297.1 / 148.6 kN·m؛ و $b_{FS} = 6.5 - 2.75 = 3.75$ م، و $MF = 3.75/3.25 = 1.154$ ← شريحة العمود المعدّلة 113.9 / 211.4 / 71.4 kN·m. **العمود الطرفي** بياخد $P = 1.1\\times15.1\\times3.25\\times5.5 = 296.9$ kN لكل دور، يعني 1484.5 kN في الدور الأرضي، مع 98.8 kN·m من الإطار؛ و $\\lambda = 1.3\\times(4.0 - 0.22)/0.5 = 9.8 < 10$ — عمود قصير الحد الأدنى للحديد فيه، $0.8\\%\\times500^2 = 2000$ مم² (12Ø16)، هو اللي بيحكم."}},{t:"p",text:{en:"**Example — mixing the methods on a roof** (4 × 7.0 m along x; along y a 1.5 m cantilever, 6.0 + 6.0 m and another 1.5 m cantilever; fcu 30, fy 400, F.C. 3.0, L.L. 3.0, h = 4.0 m): $t_s = 220$, $w_s = 16.7$ kN/m²; 350 mm columns punch (1.95 > 1.41), 600 × 600 pass ($Q_{up} = 691.0$ kN, $q_{up} = 1.32$). Along x four bays qualify: $M_o = 16.7\\times6.0\\times(7.0 - 0.4)^2/8 = 545.6$ kN·m → column strip 136.4 / 163.7 / 272.8 / 245.5, field strip 27.3 / 109.1 / 81.8 kN·m. Along y only two bays → a one-storey frame 7.0 m wide ($w = 116.9$ kN/m) with columns below only: $I_c = 0.6\\times600^4/12 = 6.48\\times10^9$, $I_s = 7000\\times220^3/12 = 6.21\\times10^9$ mm⁴, $K_s = 1.035\\times10^6$ (not halved — the axis passes through the middle column) and $K_c = 1.62\\times10^6$ mm³ → D.F. 0.39 (slab) / 0.61 (column). At the edge joint the cantilever, $116.9\\times1.5^2/2 = 131.5$ kN·m, balances part of $FEM = 350.7$: the joint releases $0.39\\times219.2 = 85.5$ → **−265.2** at the edge, **393.4** at the middle, **196.7** at mid-span, and 133.7 kN·m into the column (66.9 at its foot). The cantilever splits $131.5\\times3.0/7.0 = 56.4$ (CS) and 75.2 (FS) with no MF; the rest with $MF = 4.0/3.5$ → column strip 204.6 / 281.0 / 95.5 kN·m. At the edge support the field strip takes $\\max(75.2,\\ 60.6) = 75.2$ kN·m — its cantilever share governs.",ar:"**مثال — طريقتين في سطح واحد** (4 × 7.0 م على x؛ وعلى y كابولي 1.5 م، و 6.0 + 6.0 م، وكابولي تاني 1.5 م؛ و fcu 30، و fy 400، والتشطيبات 3.0، والحمل الحي 3.0، و h = 4.0 م): $t_s = 220$، و $w_s = 16.7$ kN/m²؛ الأعمدة 350 مم بتتخرم (1.95 > 1.41)، والـ 600 × 600 بتعدّي ($Q_{up} = 691.0$ kN، و $q_{up} = 1.32$). على x أربع بواكي بتحقق الشروط: $M_o = 16.7\\times6.0\\times(7.0 - 0.4)^2/8 = 545.6$ kN·m ← شريحة العمود 136.4 / 163.7 / 272.8 / 245.5، والوسطى 27.3 / 109.1 / 81.8 kN·m. وعلى y باكيتين بس ← إطار دور واحد عرضه 7.0 م ($w = 116.9$ kN/m) وأعمدته تحت بس: $I_c = 0.6\\times600^4/12 = 6.48\\times10^9$، و $I_s = 7000\\times220^3/12 = 6.21\\times10^9$ مم⁴، و $K_s = 1.035\\times10^6$ (من غير تنصيف — المحور بيعدّي في العمود الأوسط) و $K_c = 1.62\\times10^6$ مم³ ← D.F. = 0.39 (بلاطة) / 0.61 (عمود). عند العقدة الطرفية الكابولي، $116.9\\times1.5^2/2 = 131.5$ kN·m، بيوازن جزء من $FEM = 350.7$: العقدة بتفك $0.39\\times219.2 = 85.5$ ← **−265.2** عند الطرف، و **393.4** في النص، و **196.7** في نص البحر، و 133.7 kN·m للعمود (66.9 عند رجله). الكابولي بيتقسم $131.5\\times3.0/7.0 = 56.4$ (شريحة العمود) و 75.2 (الوسطى) من غير MF؛ والباقي بـ $MF = 4.0/3.5$ ← شريحة العمود 204.6 / 281.0 / 95.5 kN·m. وعند الركيزة الطرفية الشريحة الوسطى بتاخد $\\max(75.2,\\ 60.6) = 75.2$ kN·m — نصيبها من الكابولي هو اللي بيحكم."}},{t:"quiz",q:{kind:"num",q:{en:"The frame analysis gives a span moment of 200 kN·m. How much goes to the column strip (kN·m)?",ar:"تحليل الإطار بيدي عزم بحر 200 kN·m. شريحة العمود بتاخد قد إيه (kN·m)؟"},answer:110,tol:.001,unit:"kN·m",explain:{en:"Spans: 55 % to the column strip, $0.55\\times200 = 110$ kN·m (the field strip takes 90).",ar:"البحور: 55 % لشريحة العمود، $0.55\\times200 = 110$ kN·m (والوسطى بتاخد 90)."}}}]},{id:"special",title:{en:"Special flat slabs: cantilevers, openings, slopes and curves",ar:"بلاطات لاكمرية خاصة: كوابيل وفتحات وميول ومنحنيات"},blocks:[{t:"p",text:{en:"Real floors rarely stop at a neat grid. This section collects what the rules so far leave out — cantilever edges, openings, sloping and curved slabs, a footbridge, slabs that meet other systems and design with a computer model — and ends with the whole procedure in seven steps.",ar:"الأدوار الحقيقية نادراً ما بتقف عند شبكة مرتبة. الجزء ده بيجمع اللي القواعد اللي فاتت ماغطّتهوش — أحرف الكوابيل، والفتحات، والبلاطات المائلة والمنحنية، وكوبري مشاة، والبلاطات اللي بتقابل أنظمة تانية، والتصميم بنموذج على الكمبيوتر — وبيخلص بالطريقة كلها في سبع خطوات."}},{t:"h",text:{en:"Cantilever edges",ar:"أحرف الكوابيل"}},{t:"eq",tex:["M_{cant} = \\dfrac{w_s\\,L_c^2}{2},\\qquad M_{cant,CS} = M_{cant}\\,b_{CS},\\qquad M_{cant,FS} = M_{cant}\\,b_{FS}"],caption:{en:"Per metre (kN·m/m), then per strip by the actual widths. Cantilever moments are never multiplied by the modification factor — MF only corrects the panel moments. At the cantilever support design the column strip for the larger of M_cant,CS and its exterior value (0.25 M_o, or 0.20 M_o with a marginal beam, after MF), and the field strip for the larger of M_cant,FS and 0.05 M_o (0.10 M_o).",ar:"للمتر (kN·m/m)، وبعدين للشريحة بعرضها الحقيقي. عزوم الكابولي عمرها ما بتتضرب في معامل التعديل — MF بيصلّح عزوم الباكية بس. وعند ركيزة الكابولي صمم شريحة العمود على الأكبر من M_cant,CS وقيمتها الخارجية (0.25 M_o، أو 0.20 M_o مع كمرة طرفية، بعد MF)، والشريحة الوسطى على الأكبر من M_cant,FS و 0.05 M_o (أو 0.10 M_o)."}},{t:"steps",items:[{en:"**Top bars as hairpins** (شوكة): $L_c$ into the cantilever and $1.5\\,L_c$ back into the span.",ar:"**الحديد العلوي على شكل شوكة**: $L_c$ جوه الكابولي و $1.5\\,L_c$ راجع جوه البحر."},{en:"**A cantilever of varying length:** if its tip lies opposite the field strip, ignore it for the column strip and design the field-strip end for $\\max(0.05\\,M_o,\\ M_{cant,FS})$ with the full $L_c$; if the tip lies opposite the column strip, the other way round.",ar:"**كابولي طوله متغير:** لو طرفه قصاد الشريحة الوسطى، إهمله في شريحة العمود وصمم طرف الشريحة الوسطى على $\\max(0.05\\,M_o,\\ M_{cant,FS})$ بطول $L_c$ كامل؛ ولو طرفه قصاد شريحة العمود، العكس."},{en:"**Bars parallel to the edge inside the cantilever:** without a marginal beam the band $L_c + b_{CS}/2$ is a column strip and gets the same steel as an interior column strip; with a marginal beam the cantilever is a solid cantilever slab with 5Ø10/m top and bottom along the edge, outside the last column strip.",ar:"**الأسياخ الموازية للحرف جوه الكابولي:** من غير كمرة طرفية الشريط $L_c + b_{CS}/2$ بيبقى شريحة عمود وبياخد نفس حديد شريحة العمود الداخلية؛ ومع كمرة طرفية الكابولي بيبقى بلاطة كابولي مصمتة عليها 5Ø10 في المتر فوق وتحت موازية للحرف، ومش جزء من آخر شريحة عمود."},{en:"**Parapets:** a parapet running along a strip is a line load on that strip; one across the end of a strip is a point load at the cantilever tip.",ar:"**الدروة:** الدروة الماشية مع الشريحة حمل خطي عليها؛ واللي بعرض طرف الشريحة حمل مركز عند طرف الكابولي."}]},{t:"p",text:{en:"**The cantilever floor of section 7, short direction** (strips 6.75 m wide; drop panels 3.0 m → CS 3.0 m, FS 3.75 m; $w_s = 18.275$): $M_o = 18.275\\times6.75\\times(6.0 - 0.233)^2/8 = 512.8$ kN·m and the cantilever $18.275\\times2.0^2/2 = 36.55$ kN·m/m → $M_{cant,CS} = 109.65$, $M_{cant,FS} = 137.1$ kN·m. $MF = 3.75/3.375 = 1.111$ acts on the panel moments only: field strip 28.5 / 113.9 / 85.5 and column strip 125.3 / 245.0 / 222.2 kN·m at the supports, column strip 142.4 / 119.6 in the spans. At the cantilever support the column strip keeps its coefficient value, $\\max(109.65,\\ 125.3) = 125.3$, but the field strip is ruled by the cantilever, $\\max(137.1,\\ 28.5) = 137.1$ kN·m: 36.55 kN·m/m with $d = 160$ → $C_1 = 4.58$, 696 mm²/m → 7Ø12/m, bent as hairpins 2.0 m out and 3.0 m back.",ar:"**دور الكابولي بتاع الجزء 7، الاتجاه القصير** (الشرائح عرضها 6.75 م؛ والسقوط 3.0 م ← شريحة العمود 3.0 م والوسطى 3.75 م؛ و $w_s = 18.275$): $M_o = 18.275\\times6.75\\times(6.0 - 0.233)^2/8 = 512.8$ kN·m والكابولي $18.275\\times2.0^2/2 = 36.55$ kN·m/m ← $M_{cant,CS} = 109.65$ و $M_{cant,FS} = 137.1$ kN·m. و $MF = 3.75/3.375 = 1.111$ بيشتغل على عزوم الباكية بس: الشريحة الوسطى 28.5 / 113.9 / 85.5 وشريحة العمود 125.3 / 245.0 / 222.2 kN·m عند الركائز، وشريحة العمود 142.4 / 119.6 في البحور. وعند ركيزة الكابولي شريحة العمود بتفضل على قيمة المعامل، $\\max(109.65,\\ 125.3) = 125.3$، لكن الشريحة الوسطى الكابولي هو اللي بيحكمها، $\\max(137.1,\\ 28.5) = 137.1$ kN·m: يعني 36.55 kN·m/m بـ $d = 160$ ← $C_1 = 4.58$ و 696 مم²/م ← 7Ø12 في المتر، متنية شوكة 2.0 م لبرّه و 3.0 م لجوه."}},{t:"p",text:{en:"**Example — a shed on four columns** (2.0 + 6.0 + 2.0 m each way, H = 5.5 m, 400 × 400 columns, a 200 × 800 parapet on every edge; fcu 25, fy 400, F.C. 2.5, L.L. 1.5). The cantilevers set the thickness: $\\max(6000/36,\\ 2000/10) = 200$ mm; $w_s = 12.9$ kN/m² and the parapet $1.4\\times0.2\\times0.8\\times25 = 5.6$ kN/m. Punching (slab on every side of the column, so an interior section): $Q_{up} = 12.9\\times(25 - 0.57^2) + 5.6\\times10 = 374.3$ kN → $q_{up} = 1.11 < 1.29$ ✓. The frame (5.0 m wide) is symmetric about mid-span, so the half span has $K_s = \\tfrac{1}{2}I_s/L$ → D.F. 0.544 (slab) / 0.456 (column). Loads: $w = 12.9\\times5.0 + 5.6 = 70.1$ kN/m (the parapet along the strip) and a tip load $5.6\\times5.0 = 28.0$ kN (the parapet across its end); cantilever $70.1\\times2.0^2/2 + 28.0\\times2.0 = 196.2$ kN·m against $FEM = 210.3$ → support −202.6, mid-span 112.8 kN·m. Strips: $b_{CS} = 1.5 + 2.0 = 3.5$ m, $b_{FS} = 1.5$ m, $MF = 1.5/2.5 = 0.60$: cantilever 137.3 (CS) / 58.9 (FS); support CS 178.3, FS 24.3; span CS 82.4, FS 30.5 kN·m. The slab is symmetric both ways, so one design with $d = 160$ serves both directions: CS support $178.3/3.5 = 50.9$ kN·m/m → 6Ø16/m; FS at the cantilever $58.9/1.5 = 39.2$ kN·m/m → 7Ø12/m.",ar:"**مثال — مظلة على أربع أعمدة** (2.0 + 6.0 + 2.0 م في كل اتجاه، و H = 5.5 م، وأعمدة 400 × 400، ودروة 200 × 800 على كل الأحرف؛ و fcu 25، و fy 400، والتشطيبات 2.5، والحمل الحي 1.5). الكوابيل هي اللي بتحدد التخانة: $\\max(6000/36,\\ 2000/10) = 200$ مم؛ و $w_s = 12.9$ kN/m² والدروة $1.4\\times0.2\\times0.8\\times25 = 5.6$ kN/m. القص الثاقب (البلاطة حوالين العمود من كل ناحية، يعني قطاع داخلي): $Q_{up} = 12.9\\times(25 - 0.57^2) + 5.6\\times10 = 374.3$ kN ← $q_{up} = 1.11 < 1.29$ ✓. الإطار (عرضه 5.0 م) متماثل حوالين نص البحر، فنص البحر بياخد $K_s = \\tfrac{1}{2}I_s/L$ ← D.F. = 0.544 (بلاطة) / 0.456 (عمود). الأحمال: $w = 12.9\\times5.0 + 5.6 = 70.1$ kN/m (الدروة الماشية مع الشريحة) وحمل مركز عند الطرف $5.6\\times5.0 = 28.0$ kN (الدروة اللي بعرض طرفها)؛ الكابولي $70.1\\times2.0^2/2 + 28.0\\times2.0 = 196.2$ kN·m قصاد $FEM = 210.3$ ← الركيزة −202.6، ونص البحر 112.8 kN·m. الشرائح: $b_{CS} = 1.5 + 2.0 = 3.5$ م، و $b_{FS} = 1.5$ م، و $MF = 1.5/2.5 = 0.60$: الكابولي 137.3 (شريحة العمود) / 58.9 (الوسطى)؛ والركيزة شريحة العمود 178.3 والوسطى 24.3؛ والبحر شريحة العمود 82.4 والوسطى 30.5 kN·m. البلاطة متماثلة في الاتجاهين، فتصميم واحد بـ $d = 160$ بيخدم الاتجاهين: ركيزة شريحة العمود $178.3/3.5 = 50.9$ kN·m/m ← 6Ø16 في المتر؛ والوسطى عند الكابولي $58.9/1.5 = 39.2$ kN·m/m ← 7Ø12 في المتر."}},{t:"h",text:{en:"Openings",ar:"الفتحات"}},{t:"p",text:{en:"A computer model accepts an opening of any size. To keep the empirical and frame moments valid, openings are limited by the strips they cut:",ar:"نموذج الكمبيوتر بيقبل فتحة بأي مقاس. لكن عشان عزوم الطريقة التقريبية وطريقة الإطار تفضل صالحة، الفتحات بتتحدد حسب الشرائح اللي بتقطعها:"}},{t:"table",head:[{en:"Zone",ar:"المنطقة"},{en:"largest opening",ar:"أكبر فتحة"},{en:"office floor",ar:"دور المكاتب"}],rows:[[{en:"field strip ∩ field strip (mid-panel)",ar:"وسطى ∩ وسطى (نص الباكية)"},"$0.4\\,L_1\\times0.4\\,L_2$",{en:"2.56 × 2.24 m",ar:"2.56 × 2.24 م"}],[{en:"column strip ∩ field strip",ar:"عمود ∩ وسطى"},"$0.25\\,b_{CS}\\times0.25\\,b_{FS}$",{en:"0.70 × 0.70 m (0.90 m across the 3.6 m field strips)",ar:"0.70 × 0.70 م (0.90 م على عرض الشرائح الوسطى 3.6 م)"}],[{en:"column strip ∩ column strip (at the column)",ar:"عمود ∩ عمود (عند العمود)"},"$0.05\\,L_1\\times0.05\\,L_2$",{en:"0.32 × 0.28 m",ar:"0.32 × 0.28 م"}]],caption:{en:"Each dimension is measured across the strip it cuts. Office floor: 6.4 × 5.6 m panels with 2.8 m strips. An opening close to a column also shortens the punching perimeter (section 7).",ar:"كل بُعد بيتقاس على عرض الشريحة اللي بيقطعها. دور المكاتب: بواكي 6.4 × 5.6 م وشرائح 2.8 م. والفتحة القريبة من العمود كمان بتقصّر محيط القص الثاقب (الجزء 7)."}},{t:"eq",tex:["A_s' = \\dfrac{A_s\\,b_1}{2},\\qquad L_d = 60\\,\\phi"],caption:{en:"The steel cut by the opening (A_s in mm²/m over its width b1 in m) is put back half on each side, top and bottom, and runs L_d = 60Ø beyond the opening.",ar:"الحديد اللي الفتحة قطعته (A_s بالـ mm²/m على عرضها b1 بالمتر) بيترجع نصه على كل ناحية، فوق وتحت، وبيكمّل L_d = 60Ø بعد الفتحة."}},{t:"p",text:{en:"**Example.** A 2.5 × 2.5 m opening in the middle of a panel needs panels of at least $2.5/0.4 = 6.25$ m each way. With 5Ø12/m top and bottom it cuts $565.5\\times2.5 = 1414$ mm² in each layer: 707 mm² goes to each side → **4Ø16** (804 mm²) top and bottom along every edge, extended $60\\times16 = 960$ mm past the opening. When posts stand on the edge of a large opening their loads go into the frame as point loads: an average load $w_{av} = \\sum w\\,L/L_{total}$ replaces the lighter stretch across the opening — e.g. a strip carrying 89.43 kN/m over 6 m and 69.56 kN/m over the 3 m beside the opening, $(89.43\\times6 + 69.56\\times3)/9 = 82.8$ kN/m — and two loads at the third points add $FEM = 2PL/9$ (two posts of 25.6 kN on 9.0 m: $558.9 + 51.2 = 610.1$ kN·m). Checking punching without deducting the opening is on the safe side.",ar:"**مثال.** فتحة 2.5 × 2.5 م في نص باكية محتاجة بواكي 6.25 م على الأقل في كل اتجاه ($2.5/0.4$). ومع 5Ø12 في المتر فوق وتحت الفتحة بتقطع $565.5\\times2.5 = 1414$ مم² في كل طبقة: 707 مم² بيروحوا لكل ناحية ← **4Ø16** (804 مم²) فوق وتحت على كل حرف، بيكمّلوا $60\\times16 = 960$ مم بعد الفتحة. ولما يكون فيه عواميد صغيرة (Posts) واقفة على حرف فتحة كبيرة، أحمالها بتدخل الإطار أحمال مركزة: حمل متوسط $w_{av} = \\sum w\\,L/L_{total}$ بيحل محل الجزء الأخف اللي بيعدّي على الفتحة — مثلاً شريحة شايلة 89.43 kN/m على 6 م و 69.56 kN/m على الـ 3 م اللي جنب الفتحة، $(89.43\\times6 + 69.56\\times3)/9 = 82.8$ kN/m — وحملين عند التلتين بيزوّدوا $FEM = 2PL/9$ (عمودين كل واحد 25.6 kN على 9.0 م: $558.9 + 51.2 = 610.1$ kN·m). ومراجعة القص الثاقب من غير خصم الفتحة في ناحية الأمان."}},{t:"h",text:{en:"Sloping and curved slabs",ar:"بلاطات مائلة ومنحنية"}},{t:"eq",tex:["w_{si} = 1.4\\,(t_s\\,\\gamma_c + F.C.) + 1.6\\,L.L.\\cos\\theta","M_o = \\dfrac{w_{si}\\,L_2\\left(L_1 - \\tfrac{2D}{3}\\right)\\left(L_1' - \\tfrac{2D}{3}\\right)}{8}"],caption:{en:"Per m² of sloping slab: the live load is given on plan, so only it is multiplied by cos θ. L1 is the horizontal span, L1′ the sloping length. Along the contours the strip is a frame with the average column height, and its moments are designed as M cos θ.",ar:"لكل م² من البلاطة المائلة: الحمل الحي متحدد على المسقط الأفقي، فهو بس اللي بيتضرب في cos θ. و L1 البحر الأفقي و L1′ الطول المائل. وفي الاتجاه الأفقي الشريحة إطار بمتوسط ارتفاع الأعمدة، وعزومه بتتصمم على M cos θ."}},{t:"p",text:{en:"**Example — a sloping roof** rising 1.5 m in each of three 7.0 m bays ($\\theta = 12.09^\\circ$, $L_1' = 7.16$ m), with 1.5 + 6.0 + 6.0 + 1.5 m across; fcu 30, fy 400, F.C. 3.0, L.L. 1.5, $t_s = 240$ mm, 500 mm columns (the tallest is 7.5 m: 7500/15 = 500). $w_{si} = 1.4\\times(6.0 + 3.0) + 1.6\\times1.5\\times0.978 = 14.95$ kN/m². Down the slope (empirical): $M_o = 14.95\\times6.0\\times6.667\\times6.826/8 = 510.1$ kN·m, column strip $0.50\\,M_o = 255.1$ kN·m. Across (a frame whose strip is 7.16 m wide, measured on the slope: $w = 14.95\\times7.16 = 107.0$ kN/m; average column height 5.25 m → D.F. 0.698 / 0.302): cantilever 120.4, edge 181.0, middle 391.0, span 195.5 kN·m; $b_{CS} = 3.0$, $b_{FS} = 4.16$ m, $MF = 4.16/3.58 = 1.162$ → column strip × cos θ = 135.9 / 271.3 / 91.2 kN·m.",ar:"**مثال — سطح مائل** بيطلع 1.5 م في كل واحدة من تلات بواكي 7.0 م ($\\theta = 12.09^\\circ$، و $L_1' = 7.16$ م)، وعلى العرض 1.5 + 6.0 + 6.0 + 1.5 م؛ و fcu 30، و fy 400، والتشطيبات 3.0، والحمل الحي 1.5، و $t_s = 240$ مم، وأعمدة 500 مم (أطولها 7.5 م: 7500/15 = 500). $w_{si} = 1.4\\times(6.0 + 3.0) + 1.6\\times1.5\\times0.978 = 14.95$ kN/m². مع الميل (بالطريقة التقريبية): $M_o = 14.95\\times6.0\\times6.667\\times6.826/8 = 510.1$ kN·m، وشريحة العمود $0.50\\,M_o = 255.1$ kN·m. وعلى العرض (إطار شريحته عرضها 7.16 م متقاسة على الميل: $w = 14.95\\times7.16 = 107.0$ kN/m؛ ومتوسط ارتفاع الأعمدة 5.25 م ← D.F. = 0.698 / 0.302): الكابولي 120.4، والطرف 181.0، والنص 391.0، والبحر 195.5 kN·m؛ و $b_{CS} = 3.0$ و $b_{FS} = 4.16$ م و $MF = 4.16/3.58 = 1.162$ ← شريحة العمود × cos θ = 135.9 / 271.3 / 91.2 kN·m."}},{t:"p",text:{en:"**Circular flat slabs.** Unroll a sector into a rectangle whose span is the arc at mid-span: with 8 columns on rings of radius 6 and 12 m, $L_{av} = 2\\pi\\times9/8 = 7.07$ m. Ring strips are closed and continuous, so they take interior coefficients only: column strip 0.45 $M_o$ at the supports and 0.25 $M_o$ in the spans, field strip 0.15 $M_o$ in both. **Example** (an opening of radius 4 m, edge at 14 m; fcu 30, fy 400, F.C. 3.0, L.L. 1.0, $t_s = 200$, $w_s = 12.8$ kN/m²): an outer-ring column carries $\\pi(14^2 - 9^2)/8 = 45.2$ m² — 400 mm punches ($q_{up} = 1.70 > 1.41$), 600 mm passes (1.25). Radially $w = 12.8\\times7.07 = 90.5$ kN/m with 2.0 m cantilevers at both ends ($M = 181.0$ kN·m) and $b_{CS} = 3.0$ m of the 7.07 m set ($MF = 1.151$). The outer ring strip ($b_{CS} = 1.5 + 2.0 = 3.5$ m, $b_{FS} = 1.5$ m, $MF = 0.6$): $M_o = 12.8\\times5.0\\times(7.07 - 0.4)^2/8 = 355.9$ kN·m → column strip 181.5 kN·m at the supports and 110.3 in the spans.",ar:"**البلاطات اللاكمرية الدائرية.** افرد القطاع الدائري لمستطيل بحره هو القوس اللي في نص البحر: مع 8 أعمدة على حلقتين نصف قطرهم 6 و 12 م، $L_{av} = 2\\pi\\times9/8 = 7.07$ م. والشرائح الحلقية مقفلة ومستمرة، فبتاخد معاملات البواكي الداخلية بس: شريحة العمود 0.45 $M_o$ عند الركائز و 0.25 $M_o$ في البحور، والشريحة الوسطى 0.15 $M_o$ في الاتنين. **مثال** (فتحة نصف قطرها 4 م، والحرف عند 14 م؛ و fcu 30، و fy 400، والتشطيبات 3.0، والحمل الحي 1.0، و $t_s = 200$، و $w_s = 12.8$ kN/m²): عمود الحلقة الخارجية شايل $\\pi(14^2 - 9^2)/8 = 45.2$ م² — الـ 400 مم بيتخرم ($q_{up} = 1.70 > 1.41$)، والـ 600 مم بيعدّي (1.25). في الاتجاه القطري $w = 12.8\\times7.07 = 90.5$ kN/m بكوابيل 2.0 م من الطرفين ($M = 181.0$ kN·m)، و $b_{CS} = 3.0$ م من مجموعة 7.07 م ($MF = 1.151$). والشريحة الحلقية الخارجية ($b_{CS} = 1.5 + 2.0 = 3.5$ م، و $b_{FS} = 1.5$ م، و $MF = 0.6$): $M_o = 12.8\\times5.0\\times(7.07 - 0.4)^2/8 = 355.9$ kN·m ← شريحة العمود 181.5 kN·m عند الركائز و 110.3 في البحور."}},{t:"h",text:{en:"Two spans on hinges: a footbridge",ar:"بحرين على مفصلات: كوبري مشاة"}},{t:"p",text:{en:"For two equal spans on hinged ends no distribution is needed: the middle support acts as a fixed end, so $M_1 = wL^2/8$ there and $M_2 = wL^2/8 - M_1/2 = wL^2/16$ at mid-span. **Example — a footbridge 8.0 m wide and 18.0 m long** on edge columns at 0, 9 and 18 m ($t_s = 300$, 400 mm drop panels at the middle columns, fcu 40, fy 400, F.C. 3.0, L.L. 5.0): $w_s = 1.4\\times[(0.3 + 0.025)\\times25 + 3.0] + 1.6\\times5.0 = 23.575$ kN/m². The middle edge column on its drop panel ($d = 370$, β = 1.30, α = 3): $Q_{up} = 834.7$ kN on $b_o\\,d = 2240\\times370$ mm² → $q_{up} = 1.31 < 1.63$ ✓. Along the bridge each column line carries a 4.0 m strip: $w = 94.3$ kN/m, $M_1 = 94.3\\times9.0^2/8 = 954.8$ kN·m and $M_2 = 477.4$ kN·m, which the strips share 0.55 / 0.45 at mid-span (262.6 / 214.8). The 2.0 m column strip takes $0.75\\times954.8 = 716.1$ kN·m over the middle column → 358.0 kN·m/m with $d = 370$: $C_1 = 3.91$, so $J = 0.80$ and $A_s = 3022$ mm²/m → 8Ø22/m. (Keeping J = 0.826 here instead of reading 0.80 would leave the steel about 3 % short.) Across the bridge each 9.0 m band works as a portal frame.",ar:"في بحرين متساويين على أطراف مفصلية مش محتاجين توزيع عزوم: الركيزة الوسطية بتشتغل زي طرف ثابت، فعندها $M_1 = wL^2/8$، وفي نص البحر $M_2 = wL^2/8 - M_1/2 = wL^2/16$. **مثال — كوبري مشاة عرضه 8.0 م وطوله 18.0 م** على أعمدة على الأحرف عند 0 و 9 و 18 م ($t_s = 300$، وسقوط 400 مم عند الأعمدة الوسطانية، و fcu 40، و fy 400، والتشطيبات 3.0، والحمل الحي 5.0): $w_s = 1.4\\times[(0.3 + 0.025)\\times25 + 3.0] + 1.6\\times5.0 = 23.575$ kN/m². العمود الطرفي اللي في النص على السقوط بتاعه ($d = 370$، و β = 1.30، و α = 3): $Q_{up} = 834.7$ kN على $b_o\\,d = 2240\\times370$ مم² ← $q_{up} = 1.31 < 1.63$ ✓. على طول الكوبري كل خط أعمدة شايل شريحة 4.0 م: $w = 94.3$ kN/m، و $M_1 = 94.3\\times9.0^2/8 = 954.8$ kN·m، و $M_2 = 477.4$ kN·m بتتقسم على الشرائح 0.55 / 0.45 في نص البحر (262.6 / 214.8). وشريحة العمود 2.0 م بتاخد $0.75\\times954.8 = 716.1$ kN·m فوق العمود الأوسط ← 358.0 kN·m/m بـ $d = 370$: $C_1 = 3.91$، يبقى $J = 0.80$ و $A_s = 3022$ مم²/م ← 8Ø22 في المتر. (لو مسكت J = 0.826 هنا بدل ما تقرا 0.80، الحديد هيطلع ناقص حوالي 3 %.) وعلى عرض الكوبري كل شريط 9.0 م بيشتغل إطار بوابي (Portal frame)."}},{t:"h",text:{en:"Next to other systems",ar:"جنب أنظمة تانية"}},{t:"p",text:{en:"**A flat slab beside a solid or hollow-block slab** is solved as a separate problem. The beam between them takes the solid slab’s triangles and trapezoids on one side, acts as a marginal beam (a quarter-panel band, $L_1/4$) on the flat side, and must be designed for the torsion that side hands it. **A solid slab hung on a flat-slab cantilever** through an upstand (دروة): stiffness ranks column > beam > flat slab > solid slab, so the solid slab rests on the flat slab — its reaction per metre, plus the upstand’s own weight, is a line load at the cantilever tip.",ar:"**بلاطة لاكمرية جنب بلاطة مصمتة أو هوردي** بتتحل كمسألة لوحدها. الكمرة اللي بينهم بتاخد المثلثات وأشباه المنحرف من ناحية المصمتة، وبتشتغل كمرة طرفية (شريط ربع باكية، $L_1/4$) من ناحية اللاكمرية، ولازم تتصمم على عزم اللي الجاي لها من الناحية دي. **بلاطة مصمتة متعلقة على كابولي بلاطة لاكمرية** عن طريق دروة: ترتيب الجساءة عمود > كمرة > بلاطة لاكمرية > بلاطة مصمتة، فالمصمتة بتقعد على اللاكمرية — ورد فعلها لكل متر، زائد وزن الدروة، حمل خطي عند طرف الكابولي."}},{t:"h",text:{en:"Design with a computer model",ar:"التصميم بنموذج على الكمبيوتر"}},{t:"p",text:{en:"In a program such as SAP the slab is divided into small shell elements (the finer the mesh, the better) resting on the columns. The results are two contour maps of moment per metre — M11 for the bars along x and M22 for the bars along y — hogging drawn solid red, sagging dashed blue. Choose base meshes top and bottom, compute their capacity, and add bars only in the zones whose contours exceed it, zone by zone: the total steel is the meshes plus the additional bars.",ar:"في برنامج زي SAP البلاطة بتتقسم لعناصر Shell صغيرة (كل ما الـ Mesh تبقى أنعم كل ما النتيجة أدق) قاعدة على الأعمدة. النتيجة خريطتين كونتور للعزم لكل متر — M11 لأسياخ اتجاه x و M22 لأسياخ اتجاه y — والسالب مرسوم خط أحمر مصمت والموجب خط أزرق متقطع. اختار شبكة أساسية فوق وتحت، واحسب قدرتها، وضيف أسياخ بس في المناطق اللي الكونتور فيها أكبر منها، منطقة منطقة: الحديد الكلي = الشبك + الأسياخ الإضافية."}},{t:"eq",tex:["M_{mesh} = A_s\\,J\\,f_y\\,d,\\qquad J \\approx 0.80"],caption:{en:"A base mesh 5Ø12/m (565.5 mm²/m) top and bottom, ts = 220, fy 350: 30.1 kN·m/m for the lower layer (d = 190) and 28.5 for the upper one (d = 180).",ar:"شبكة أساسية 5Ø12 في المتر (565.5 مم²/م) فوق وتحت، و ts = 220، و fy 350: 30.1 kN·m/m للفرش (d = 190) و 28.5 للغطاء (d = 180)."}},{t:"h",text:{en:"The whole procedure",ar:"الطريقة كلها"}},{t:"steps",items:[{en:"Column size and $t_s$ — and decide on drop panels.",ar:"مقاس العمود و $t_s$ — وقرّر لو فيه سقوط."},{en:"$w_s$ (with $t_{s,av}$ over drop panels).",ar:"$w_s$ (بـ $t_{s,av}$ لو فيه سقوط)."},{en:"Punching at every column (twice with drop panels).",ar:"القص الثاقب عند كل عمود (مرتين لو فيه سقوط)."},{en:"Strips in both directions, centre line to centre line; $M_o$ by the empirical method where it applies, otherwise by frames.",ar:"الشرائح في الاتجاهين من محور لمحور؛ و $M_o$ بالطريقة التقريبية لو تنفع، وإلا بالإطارات."},{en:"Share the moments between column and field strips, with the modification factor.",ar:"وزّع العزوم على شرائح الأعمدة والشرائح الوسطى، بمعامل التعديل."},{en:"Design the sections (and the extra steel over the columns).",ar:"صمم القطاعات (والحديد الإضافي فوق الأعمدة)."},{en:"Draw the reinforcement plans — bottom and top, both directions.",ar:"ارسم لوح التسليح — سفلي وعلوي، في الاتجاهين."}]},{t:"quiz",q:{kind:"num",q:{en:"A cantilever edge: w_s = 16 kN/m², Lc = 1.5 m, the field strip is 3.0 m wide and its exterior panel moment is 0.05 M_o = 20 kN·m. Design moment of the field strip at the cantilever support (kN·m)?",ar:"حرف كابولي: w_s = 16 kN/m²، و Lc = 1.5 م، والشريحة الوسطى عرضها 3.0 م وعزمها الخارجي من الباكية 0.05 M_o = 20 kN·m. عزم تصميم الشريحة الوسطى عند ركيزة الكابولي (kN·m)؟"},answer:54,tol:.1,unit:"kN·m",explain:{en:"$M_{cant,FS} = 16\\times1.5^2/2\\times3.0 = 54$ kN·m > 20 kN·m → 54 kN·m — and it is never multiplied by MF.",ar:"$M_{cant,FS} = 16\\times1.5^2/2\\times3.0 = 54$ kN·m > 20 kN·m ← 54 kN·m — وعمره ما بيتضرب في MF."}}}]},{id:"apply",title:{en:"Your building: what if the first floor were a flat slab?",ar:"مبناك: لو الدور الأول بلاطة لاكمرية؟"},blocks:[{t:"p",text:{en:"Your first floor is a 150 mm solid slab on 250 × 600 beams. Take the beams away: same grid (axes 1–4 at 5 + 5 + 4 m, A–C at 5 + 4 m), same 300 × 500 columns (300 mm along x), storey height 3.2 m, fcu = 25, fy = 400, F.C. = 1.5 and L.L. = 2 kN/m². Without beams the walls are smeared as 1.5 kN/m², and the building keeps $U = 1.5\\,(D + L)$.",ar:"الدور الأول بتاعك بلاطة مصمتة 150 مم على كمرات 250 × 600. شيل الكمرات: نفس الشبكة (المحاور 1–4 على 5 + 5 + 4 م، و A–C على 5 + 4 م)، ونفس الأعمدة 300 × 500 (300 مم على x)، وارتفاع الدور 3.2 م، و fcu = 25 و fy = 400، والتشطيبات 1.5 والحمل الحي 2 kN/m². ومن غير كمرات الحوائط بتتفرد كـ 1.5 kN/m²، والمبنى محتفظ بـ $U = 1.5\\,(D + L)$."}},{t:"p",text:{en:"**Dimensions and loads.** $b_{min} = \\max(300,\\ 3200/15 = 213,\\ 5000/20 = 250) = 300$ mm: the 300 mm side is exactly enough — nothing to change for the size rule. The external 5 m panels need $5000/32 = 156.3$ → **$t_s = 160$ mm**, 10 mm more than now; the 1.5 m balcony needs $1500/10\\times0.971 = 145.7 \\le 160$ ✓. $g_s = 0.16\\times25 + 1.5 + 1.5 = 7.0$ and $p_s = 2.0 \\le 0.75\\,g_s$ → $w_s = 1.5\\times9.0 = 13.5$ kN/m²; the balcony (no walls, L.L. = 3) $1.5\\times(4.0 + 1.5 + 3.0) = 12.75$ kN/m². **The method.** Only 2 bays along z, and adjacent spans of 5 and 4 m differ by 20 % (> 10 %): strictly the frame method is required; the coefficients below are a first estimate.",ar:"**الأبعاد والأحمال.** $b_{min} = \\max(300,\\ 3200/15 = 213,\\ 5000/20 = 250) = 300$ مم: الضلع 300 مم كافي بالظبط — مفيش حاجة تتغير عشان قاعدة المقاس. البواكي الطرفية 5 م محتاجة $5000/32 = 156.3$ ← **$t_s = 160$ مم**، أكتر من دلوقتي بـ 10 مم؛ والبلكونة 1.5 م محتاجة $1500/10\\times0.971 = 145.7 \\le 160$ ✓. و $g_s = 0.16\\times25 + 1.5 + 1.5 = 7.0$ و $p_s = 2.0 \\le 0.75\\,g_s$ ← $w_s = 1.5\\times9.0 = 13.5$ kN/m²؛ والبلكونة (من غير حوائط، والحمل الحي 3) $1.5\\times(4.0 + 1.5 + 3.0) = 12.75$ kN/m². **الطريقة.** باكيتين بس على z، والبحور المتجاورة 5 و 4 م مختلفة 20 % (> 10 %): بالظبط كده محتاجين طريقة الإطار؛ والمعاملات اللي تحت تقدير أولي."}},{t:"table",head:[{en:"Bay",ar:"الباكية"},"$M_{o,x}$","$M_{o,z}$",{en:"column strip",ar:"شريحة العمود"},{en:"column-strip top bars, x",ar:"حديد شريحة العمود العلوي، x"},{en:"column-strip top bars, z",ar:"حديد شريحة العمود العلوي، z"}],rows:[["AB/12 · AB/23","194.4","183.8","2.5 m","38.9 → 5Ø16","36.8 → 6Ø16"],["AB/34","121.8","147.0","2.0 m","44.7 → 6Ø16","36.8 → 6Ø16"],["BC/12 · BC/23","155.5","113.4","2.0 m","38.9 → 5Ø16","42.3 → 6Ø16"],["BC/34","97.5","90.8","2.0 m","38.9 → 5Ø16","36.8 → 6Ø16"]],caption:{en:"M_o in kN·m (2c/3 = 0.20 m along x, 0.33 m along z); column strip = half the shorter side; top bars over the interior column lines in kN·m/m → bars per metre (z has d = 120 mm, so 36.8 needs more steel than 38.9 along x with d = 130). Everything else — spans, field strips, exterior supports — needs the minimum 5Ø12/m or 6Ø12/m.",ar:"M_o بالـ kN·m (و 2c/3 = 0.20 م على x و 0.33 م على z)؛ وشريحة العمود = نص الضلع الأقصر؛ والحديد العلوي فوق خطوط الأعمدة الداخلية بالـ kN·m/m ← أسياخ في المتر (z عمقها d = 120 مم، فالـ 36.8 محتاجة حديد أكتر من 38.9 على x بعمق d = 130). وكل الباقي — البحور والشرائح الوسطى والركائز الخارجية — محتاج الحد الأدنى 5Ø12/م أو 6Ø12/م."}},{t:"table",head:[{en:"Column",ar:"العمود"},{en:"section",ar:"القطاع"},"β","$b_o$ (mm)","$Q_{up}$ (kN)","$q_{up}$",{en:"used",ar:"المستخدم"}],rows:[["A1",{en:"edge*",ar:"طرفي*"},"1.30","1360","129.1","0.949","74 %"],["A2",{en:"interior*",ar:"داخلي*"},"1.15","2120","260.7","1.088","84 %"],["A3",{en:"edge*",ar:"طرفي*"},"1.30","1560","196.4","1.259","98 %"],["A4",{en:"corner",ar:"ركني"},"1.50","930","64.7","0.803","62 %"],["B1",{en:"edge",ar:"طرفي"},"1.30","1360","148.8","1.094","85 %"],["B2",{en:"interior",ar:"داخلي"},"1.15","2120","300.1","1.252","97 %"],["B3",{en:"interior",ar:"داخلي"},"1.15","2120","269.7","1.125","87 %"],["B4",{en:"edge",ar:"طرفي"},"1.30","1360","118.4","0.871","67 %"],["C1",{en:"corner",ar:"ركني"},"1.50","930","64.7","0.803","62 %"],["C2",{en:"edge",ar:"طرفي"},"1.30","1560","131.7","0.844","65 %"],["C3",{en:"edge",ar:"طرفي"},"1.30","1560","118.2","0.758","59 %"],["C4",{en:"corner",ar:"ركني"},"1.50","930","51.2","0.635","49 %"]],caption:{en:"d = 130 mm; q_cup = 0.316√(25/1.5) = 1.29 N/mm² governs everywhere. * The balcony slab continues in front of A1–A3 and its load (12.75 kN/m² × its tributary area) is added: A1 keeps only one free edge (axis 1), A2 has a full perimeter, and A3 — where the balcony stops — is kept as an edge column on the safe side.",ar:"d = 130 مم؛ و q_cup = 0.316√(25/1.5) = 1.29 N/mm² بيحكم في كل حتة. * بلاطة البلكونة مكمّلة قدام A1–A3 وحملها (12.75 kN/m² × مساحة تحميلها) بيتضاف: A1 فاضل له حرف حر واحد (المحور 1)، و A2 محيطه كامل، و A3 — اللي البلكونة بتقف عنده — بيتحسب عمود طرفي في ناحية الأمان."}},{t:"p",text:{en:"**The balcony and the strips.** Along axis A the edge column strip grows to $L_2/4 + L_c = 1.25 + 1.5 = 2.75$ m; with the balcony band inside it, it needs at most 31.8 kN·m/m — less than the 38.9 kN·m/m of the panels’ column strips, so their bars cover it. The z top bars on axis A must also hold the cantilever, $12.75\\times1.5^2/2 = 14.3$ kN·m/m (362 mm²/m) — the minimum 5Ø12/m is enough.",ar:"**البلكونة والشرائح.** على المحور A شريحة العمود الطرفية بتعرض لـ $L_2/4 + L_c = 1.25 + 1.5 = 2.75$ م؛ وشريط البلكونة جواها، ومحتاجة بالكتير 31.8 kN·m/m — أقل من 38.9 kN·m/m بتاعة شرائح أعمدة البواكي، فأسياخها مغطياها. وحديد z العلوي على المحور A لازم كمان يشيل الكابولي، $12.75\\times1.5^2/2 = 14.3$ kN·m/m (362 مم²/م) — والحد الأدنى 5Ø12/م كفاية."}},{t:"p",text:{en:"**Drop panels?** Not needed: the live load is light, every column passes and every strip has C1 above its limit — but A3 and B2 keep only 2–3 % margin. Turn the floor into offices (L.L. = 3) and B2 fails ($q_{up} = 1.391 > 1.29$): 400 × 500 columns (1.268 ✓) or drop panels would be needed. **Against the slab + beams:** the floor’s concrete drops from $18.9 + 8.4 = 27.3$ m³ (slab and beam webs) to $0.16\\times126 = 20.2$ m³ — 26 % less, 504 kN instead of 683 kN (4.0 instead of 5.4 kN/m²) — and the clear height under the ceiling grows from 2.6 m (under the beams) to 3.04 m. The price: more steel (5Ø12/m as the minimum, Ø16 over the columns), and in reality the brick façade walls would still ask for marginal beams at least $3\\times160 = 480$ mm deep.",ar:"**سقوط؟** مش محتاجين: الحمل الحي خفيف، وكل الأعمدة بتعدّي، وكل الشرائح الـ C1 بتاعها فوق الحد — بس A3 و B2 فاضل لهم هامش 2–3 % بس. حوّل الدور لمكاتب (الحمل الحي 3) وهتلاقي B2 بيفشل ($q_{up} = 1.391 > 1.29$): هنحتاج أعمدة 400 × 500 (1.268 ✓) أو سقوط. **قصاد البلاطة + الكمرات:** خرسانة الدور بتنزل من $18.9 + 8.4 = 27.3$ م³ (البلاطة وأجسام الكمرات) لـ $0.16\\times126 = 20.2$ م³ — أقل بـ 26 %، يعني 504 kN بدل 683 kN (4.0 بدل 5.4 kN/m²) — والارتفاع الصافي تحت السقف بيزيد من 2.6 م (تحت الكمرات) لـ 3.04 م. التمن: حديد أكتر (5Ø12/م حد أدنى، و Ø16 فوق الأعمدة)، وفي الحقيقة حوائط الواجهة الطوب لسه هتطلب كمرات طرفية عمقها على الأقل $3\\times160 = 480$ مم."}},{t:"lab",lab:"flatslab",height:500,props:{preset:"building",select:"C4",missions:n,defaultTab:"punching"},caption:{en:"Your first floor as a flat slab in the lab (without the balcony, so A1–A3 appear as the grid corner and edge columns): find the tightest column, then turn it into an office floor.",ar:"دورك الأول كبلاطة لاكمرية في المعمل (من غير البلكونة، فـ A1–A3 بيظهروا أعمدة ركنية وطرفية زي الشبكة): دوّر على أضيق عمود، وبعدين حوّله لدور مكاتب."}},{t:"widget",w:"building",props:{focus:"C0-B2",tags:["footings","cols-g","slab-1","balcony","materials","flat-option"]}},{t:"quiz",q:{kind:"mcq",q:{en:"A2 stands on the edge axis A, yet it is checked with a full (interior) perimeter. Why?",ar:"A2 واقف على المحور الطرفي A، ومع ذلك بيتراجع بمحيط كامل (داخلي). ليه؟"},options:[{en:"The balcony slab continues in front of it, so no side of its perimeter is cut",ar:"بلاطة البلكونة مكمّلة قدامه، فمفيش ضلع من محيطه مقطوع"},{en:"Its 500 mm side is deep enough",ar:"ضلعه 500 مم عميق كفاية"},{en:"Every column of a flat slab uses β = 1.15",ar:"كل أعمدة البلاطة اللاكمرية بتستخدم β = 1.15"}],answer:0,explain:{en:"The 1.5 m balcony runs from axis 1 to axis 3, so in front of A2 there is slab on both sides: interior section, β = 1.15, with the balcony load added.",ar:"البلكونة 1.5 م ماشية من المحور 1 للمحور 3، فقدام A2 فيه بلاطة من الناحيتين: قطاع داخلي و β = 1.15، مع إضافة حمل البلكونة."}}}]}],quiz:[{kind:"num",q:{en:"Flat slab with drop panels: the largest external panel has L1 = 7.2 m, the largest internal one L1 = 7.6 m. ts after rounding (mm)?",ar:"بلاطة لاكمرية بسقوط: أكبر باكية طرفية L1 = 7.2 م، وأكبر باكية داخلية L1 = 7.6 م. قيمة ts بعد التقريب (مم)؟"},answer:200,tol:0,unit:"mm",explain:{en:"With drops: $7200/36 = 200$ and $7600/40 = 190$ → 200 mm.",ar:"بالسقوط: $7200/36 = 200$ و $7600/40 = 190$ ← 200 مم."}},{kind:"mcq",q:{en:"β for an edge column in the punching check is…",ar:"قيمة β للعمود الطرفي في مراجعة القص الثاقب…"},options:[{en:"1.15",ar:"1.15"},{en:"1.30",ar:"1.30"},{en:"1.50",ar:"1.50"}],answer:1,explain:{en:"1.15 interior, 1.30 edge, 1.50 corner.",ar:"1.15 داخلي، و 1.30 طرفي، و 1.50 ركني."}},{kind:"num",q:{en:"Column height H = 4.8 m, longer span L1 = 7.0 m. Minimum column side (mm)?",ar:"ارتفاع العمود H = 4.8 م، والبحر الأطول L1 = 7.0 م. أقل ضلع للعمود (مم)؟"},answer:350,tol:0,unit:"mm",explain:{en:"$\\max(300,\\ 4800/15 = 320,\\ 7000/20 = 350) = 350$ mm (already a multiple of 50).",ar:"$\\max(300,\\ 4800/15 = 320,\\ 7000/20 = 350) = 350$ مم (مضاعف 50 أصلاً)."}},{kind:"num",q:{en:"w_s = 15 kN/m², panel 6.0 m (span) × 5.0 m (width), column 450 mm in the span direction. M_o (kN·m)?",ar:"w_s = 15 kN/m²، وباكية 6.0 م (بحر) × 5.0 م (عرض)، وعمود 450 مم في اتجاه البحر. قيمة M_o (kN·m)؟"},answer:304.59,tol:.002,unit:"kN·m",explain:{en:"$15\\times5.0\\times(6.0 - 2\\times0.45/3)^2/8 = 75\\times5.7^2/8 = 304.6$ kN·m.",ar:"$15\\times5.0\\times(6.0 - 2\\times0.45/3)^2/8 = 75\\times5.7^2/8 = 304.6$ kN·m."}},{kind:"tf",q:{en:"Shear stirrups may be used against punching in a 200 mm flat slab.",ar:"ممكن نستخدم كانات ضد القص الثاقب في بلاطة لاكمرية تخانتها 200 مم."},answer:!1,explain:{en:"Only when the slab is at least 250 mm thick; thinner slabs need a bigger column, a thicker slab, a drop panel or a head.",ar:"بس لو البلاطة 250 مم أو أتخن؛ البلاطات الأرفع محتاجة عمود أكبر أو تخانة أكبر أو سقوط أو تاج."}},{kind:"mcq",q:{en:"At the first interior support the column strip takes…",ar:"عند أول ركيزة وسطية شريحة العمود بتاخد…"},options:[{en:"0.45 M_o",ar:"0.45 M_o"},{en:"0.50 M_o",ar:"0.50 M_o"},{en:"0.25 M_o",ar:"0.25 M_o"}],answer:1,explain:{en:"0.50 M_o (0.45 at the other interior supports, 0.25 at the exterior one); the field strip 0.20 M_o.",ar:"0.50 M_o (و 0.45 عند الركائز الداخلية التانية، و 0.25 عند الخارجية)؛ والشريحة الوسطى 0.20 M_o."}},{kind:"num",q:{en:"fcu = 30 N/mm². The punching limit 0.316√(fcu/γc) (N/mm²)?",ar:"fcu = 30 N/mm². حد القص الثاقب 0.316√(fcu/γc) (N/mm²)؟"},answer:1.413,tol:.003,unit:"N/mm²",explain:{en:"$0.316\\times\\sqrt{30/1.5} = 0.316\\times4.472 = 1.413$ N/mm².",ar:"$0.316\\times\\sqrt{30/1.5} = 0.316\\times4.472 = 1.413$ N/mm²."}},{kind:"mcq",q:{en:"A 7.0 × 5.6 m panel has drop panels 2.6 m wide. Its column strip is…",ar:"باكية 7.0 × 5.6 م عليها سقوط عرضه 2.6 م. شريحة العمود بتبقى…"},options:[{en:"2.8 m (L2/2)",ar:"2.8 م (L2/2)"},{en:"2.6 m (the drop panel)",ar:"2.6 م (السقوط)"},{en:"3.5 m (L1/2)",ar:"3.5 م (L1/2)"}],answer:1,explain:{en:"With drop panels the column strip is as wide as the drop panel, X = 2.6 m.",ar:"مع السقوط شريحة العمود بعرض السقوط، X = 2.6 م."}}]};export{i as default};
